            'orig_thread_html_help' => 'वरीलप्रमाणे, शिवाय प्रत्येक मूळ तिकिटाची स्वयंपूर्ण HTML प्रत मर्ज केलेल्या तिकिटाला जोडली जाते — FreeITSM बाहेरील कोणालातरी संपूर्ण नोंद द्यायची असते तेव्हा सोयीचे.',
            'orig_html' => 'फक्त HTML फाइल्स म्हणून जोडलेली',
