            'ai_label' => 'तिकिटे मर्ज केल्यावर AI सारांश लिहा',
            'ai_help' => 'मर्ज केलेल्या तिकिटात प्रत्येक विनंती करणाऱ्याने काय विचारले आणि आधीच काय केले गेले आहे याचा सारांश देणारी नोंद जोडते, जेणेकरून जो ते हाती घेईल त्याला प्रत्येक संभाषण वाचावे लागत नाही. उत्तर क्लीनअप टॅबवर AI प्रदाता कॉन्फिगर केलेला असणे आवश्यक. त्याशिवायही मर्ज करणे चालते.',
            'note' => 'मर्ज केलेली तिकिटे कधीही हटवली जात नाहीत. तुम्ही कोणताही पर्याय निवडला तरी जुना संदर्भ नेहमी शोधता येतो आणि तो कुठे गेला ते दाखवतो &mdash; आणि त्याबद्दलच्या ईमेलला उत्तर देणारा ग्राहक अजूनही तुमच्यापर्यंत पोहोचतो.',
