            'notify_desc' => 'तेच, शिवाय खालील लोकांना तिकीट, रिकामी फील्ड आणि कोणी बंद केले हे सांगणारा ईमेल मिळतो - उदाहरणार्थ सेवा वितरण व्यवस्थापक.',
