            'block_desc' => 'खूण केलेली प्रत्येक फील्ड भरेपर्यंत तिकीट बंद स्थितीत जाऊ शकत नाही.',
            'record_title' => 'तिकिटावर नोंदवा',
            'record_desc' => 'रिकामी फील्ड, तिकीट कोणी बंद केले आणि कसे हे सांगणारी अंतर्गत टीप लिहिते. फक्त दोन चेतावणी पर्यायांना लागू होते - नाकारलेल्या बंद करण्याने काहीही बदलत नाही, म्हणून नोंदवण्यासारखे काही नसते.',
            'record_blocked' => 'बंद करणे नाकारले जाते तेव्हा काहीही नोंदवले जात नाही, कारण तिकीट बंद होत नाही.',
