            'fields_hint' => 'तिकिटाच्या कंपनीसाठी बंद केलेले फील्ड, किंवा संघ नसलेल्या इन्स्टॉलेशनवरील संघ फील्ड, त्या तिकिटासाठी वगळले जाते - ज्याला जे दिसत नाही ते भरण्यास कोणालाही सांगितले जात नाही. तिकिटे विलीन करताना हे कधीही लागू होत नाही.',
            'choose_mode' => 'फील्ड रिकामी असताना काय होईल ते निवडा.',
