        'intros' => [
            'custom_fields' => 'एखाद्या प्रकारच्या तिकिटाला लागणारे अतिरिक्त तपशील तयार करा - उदाहरणार्थ नवीन कर्मचाऱ्याची सुरुवात तारीख आणि वापरकर्तानाव - आणि प्रत्येक कोणत्या तिकीट प्रकारांवर असेल ते निवडा. प्रत्येक फील्ड स्वतः ठरवते की ते तिकीट नोंदवताना, बंद करताना किंवा दोन्ही वेळी भरणे आवश्यक आहे का, आणि पोर्टलवर विनंती करणाऱ्याला ते विचारले जावे का.',
            'checklists' => 'चेकलिस्ट पायऱ्या अनिवार्य म्हणून चिन्हांकित करू शकते. त्या पायऱ्यांवर खूण होण्यापूर्वी कोणी तिकीट बंद केल्यास काय होईल हे येथे ठरते.',
            'mandatory_fields' => 'तिकीट बंद करण्यापूर्वी कोणती तिकीट फील्ड भरणे आवश्यक आहे आणि त्यापैकी कोणतीही रिकामी असताना कोणी तिकीट बंद केल्यास काय होईल ते निवडा. हा नियम तिकीट बंद करता येणाऱ्या प्रत्येक ठिकाणी लागू होतो: तिकीट स्क्रीन, बल्क क्रिया, REST API आणि वर्कफ्लो.',
            'departments' => 'विभाग तिकिटांचे गट करतात आणि त्यांना तुमच्या संस्थेच्या योग्य भागाकडे पाठवतात - तुमचा सर्व्हिस डेस्क काम वर्गीकृत करण्यासाठी आणि नेमण्यासाठी वापरतो ते विभाग तयार करा.',
            'teams' => 'कोणत्या विभागांमध्ये विश्लेषक प्रवेश करू शकतात हे संघ ठरवतात. विभाग संघांना नेमा, मग प्रवेश नियंत्रित करण्यासाठी विश्लेषकांना संघांना नेमा.',
            'ticket_types' => 'तिकीट प्रकार विनंती कशाबद्दल आहे ते वर्गीकृत करतात (उदा. Incident, Service Request) - विश्लेषक तिकिटावर सेट करू शकतील असे प्रकार परिभाषित करा.',
            'ticket_origins' => 'तिकीट स्रोत तिकीट कसे आले ते नोंदवतात (उदा. ईमेल, फोन, पोर्टल) - विश्लेषक ज्यातून निवडू शकतील असे स्रोत परिभाषित करा.',
            'mailboxes' => 'मेलबॉक्स FreeITSM ला ईमेल खात्यांशी जोडतात, जेणेकरून येणारे संदेश तिकिटे बनतात आणि उत्तरे परत जातात - तुमचा सर्व्हिस डेस्क जे मेलबॉक्स पाहतो ते जोडा आणि प्रमाणित करा.',
            'privacy' => 'तिकिटात फक्त ते नोंदवणाऱ्या व्यक्तीशी झालेला तुमचा संवादच नसतो. पुरवठादाराला फॉरवर्ड करणे किंवा सहकाऱ्याला कॉपी करणे तो संदेश त्याच तिकिटावर ठेवते — आणि त्यांचे उत्तरही तिथेच येते. यापैकी किती भाग विनंती करणाऱ्याला सेल्फ-सर्व्हिस पोर्टलमध्ये दिसेल हे येथे ठरते.',
            'indexing' => 'जोडपत्रांमधील मजकूर शोधता यावा म्हणून वाचला जातो. Word, Excel, PowerPoint आणि साध्या मजकूर फायली येताच FreeITSM स्वतः वाचते. PDF, जुन्या Office फायली आणि स्कॅन केलेल्या दस्तऐवजांसाठी स्वतंत्र दस्तऐवज-वाचन सेवा लागते — ती <strong>System &rarr; Integrations &rarr; Apache Tika</strong> अंतर्गत सेट करा — आणि त्यांना जास्त वेळ लागत असल्याने ते पार्श्वभूमीत वाचले जातात. ते पार्श्वभूमीचे काम केव्हा होईल हे हे दोन स्विच ठरवतात.',
            'merge_behaviour' => 'दोन तिकिटे एकच गोष्ट असल्याचे लक्षात आल्यावर विश्लेषक त्यांना विलीन करू शकतो. तुमच्या विनंती करणाऱ्यांकडे असलेल्या तिकीट संदर्भांचे आणि संभाषणांचे काय होते हे हे सेटिंग्ज ठरवतात. ते सर्वांना लागू होतात — विलीनीकरणामुळे ग्राहकाला दिसणारे बदलते, म्हणून एकाच मेलबॉक्सवरील दोन विश्लेषकांचे त्याबाबत मतभेद होऊ नयेत.',
            'reply_templates' => 'तयार उत्तरे जी तुमचे विश्लेषक पुन्हा टाइप करण्याऐवजी उत्तरात टाकू शकतात. ही संपूर्ण संघाला दिसणारी सामायिक आहेत — विश्लेषकाचे स्वतःचे खाजगी टेम्पलेट उत्तर विंडोतून जतन केले जातात आणि येथे दाखवले जात नाहीत.',
            'rota_shifts' => 'शिफ्ट हे कामाच्या पद्धतीचे टेम्पलेट आहेत (उदा. सकाळची, संध्याकाळची, ऑन-कॉल) जे विश्लेषकांना स्टाफ रोटावर नेमले जातात — रोटा तयार करण्यापूर्वी ते येथे परिभाषित करा.',
            'analysts' => 'विश्लेषक हे लॉग इन करून तिकिटांवर काम करणारे कर्मचारी आहेत — त्यांना जोडा, पासवर्ड रीसेट करा आणि त्यांचा प्रवेश नियंत्रित करण्यासाठी संघांना नेमा.',
            'general' => 'सर्वसाधारण सेटिंग्ज तिकिटे कशी वागतात ते नियंत्रित करतात - पुन्हा उघडणे, स्नूझ करणे आणि संदेश व थ्रेड किती काळ दाखवले जातात.',
            'statuses' => 'तिकीट ज्या कार्यप्रवाह स्थितींमध्ये असू शकते त्या. <em>बंद</em> म्हणून चिन्हांकित स्थिती अंतिम मानल्या जातात — अहवाल, watchtower काउंटर आणि नेमताना बंद-तारीख आपोआप सेट करण्यासाठी वापरल्या जातात. नवीन तिकिटांसाठी नेमकी एक स्थिती डीफॉल्ट असते.',
            'priorities' => 'तिकिटांवर दाखवले जाणारे प्राधान्य स्तर. नवीन तिकिटांसाठी नेमके एक प्राधान्य डीफॉल्ट असते.',
            'rota_locations' => 'दिलेल्या दिवशी प्रत्येक विश्लेषक कुठे काम करत आहे — स्टाफ रोटाद्वारे वापरले जाते आणि प्रत्येक नोंदीवर रंगीत बॅज म्हणून दाखवले जाते. नवीन रोटा नोंदींसाठी नेमके एक स्थान डीफॉल्ट असते.',
            'email_templates' => 'तिकिटाच्या घटनांमुळे सुरू होणारी स्वयंचलित ईमेल उत्तरे. प्रत्येक घटनेसाठी फक्त पहिला सक्रिय टेम्पलेट वापरला जातो.',
        ],
        'messaging' => [
            'channels_heading' => 'मेसेजिंग चॅनेल',
            'channels_intro' => 'ग्राहकांना WhatsApp वर विश्लेषकाशी चॅट करू द्या — प्रत्येक संदेश ईमेलप्रमाणेच एक तिकीट बनतो. खाली चॅनेल जोडा, मग येणारे संदेश या इन्स्टॉलेशनपर्यंत पोहोचण्यासाठी त्याची <strong>webhook URL</strong> तुमच्या प्रदात्याकडे (Twilio किंवा Meta) पेस्ट करा.',
            'base_url_label' => '<strong>सार्वजनिक बेस URL</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (किंवा चाचणी करताना तुमचा ngrok पत्ता)',
            'base_url_help' => 'प्रदाते या इन्स्टॉलेशनपर्यंत पोहोचण्यासाठी वापरतात तो पत्ता. तो सेट करा म्हणजे खालील webhook URL कॉपी-पेस्ट करण्यास तयार होतील. तुम्ही ज्या पत्त्यावरून ब्राउझ करत आहात तोच वापरण्यासाठी रिकामे सोडा. स्थानिक पातळीवर चाचणी करत आहात? <code>ngrok http 80</code> चालवा आणि तो छापत असलेला <code>https://…ngrok-free.dev</code> पत्ता पेस्ट करा.',
            'templates_heading' => 'संदेश टेम्पलेट',
            'templates_intro' => 'पूर्व-मंजूर टेम्पलेट विश्लेषकाला <strong>24 तासांची मुदत संपल्यानंतर</strong> उत्तर देऊ देतात. WhatsApp ग्राहकाच्या शेवटच्या संदेशानंतर 24 तासांतच मुक्त मजकूर परवानगी देते; त्यानंतर फक्त Meta/Twilio ने मंजूर केलेला टेम्पलेट पाठवता येतो. प्रदात्याकडे टेम्पलेट तयार करा आणि मंजूर करा &amp; मग विश्लेषकांना निवडून भरता यावे म्हणून त्याची व्याख्या येथे जोडा (<code>{{1}}</code>, <code>{{2}}</code> प्लेसहोल्डरसह).',
        ],
        'webchat' => [
            'heading' => 'वेब चॅट विजेट',
            'intro' => 'कोणत्याही वेबसाइटवर चॅट विंडो ठेवा — अभ्यागत संदेश टाइप करतो, तो तिकीट बनतो, आणि विश्लेषक इतर कोणत्याही चॅनेलप्रमाणे इनबॉक्समधून उत्तर देतात. खाली विजेट जोडा, मग त्याचा एम्बेड स्निपेट साइटवर पेस्ट करा.',
            'col_key' => 'विजेट की',
            'col_origins' => 'वेबसाइट',
            'any_origin' => 'कोणतीही (मर्यादित नाही)',
            'add_title' => 'वेब चॅट विजेट जोडा',
            'edit_title' => 'वेब चॅट विजेट संपादित करा',
            'name' => 'नाव',
            'name_placeholder' => 'उदा. Acme वेबसाइट',
            'company' => 'कंपनी',
            'company_help' => 'या विजेटमधील प्रत्येक संभाषण एका कंपनीशी जोडा. एकाच कंपनीच्या इन्स्टॉलेशनवर सेट न केलेले ठेवा.',
            'greeting' => 'स्वागत संदेश',
            'greeting_placeholder' => 'नमस्कार! आम्ही कशी मदत करू शकतो?',
            'accent' => 'ॲक्सेंट रंग',
