            'col_default' => 'डीफॉल्ट',
            'col_actions' => 'क्रिया',
            'notifs_heading' => 'उल्लंघन सूचना',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">सूचना नियम कसे काम करतात</strong>प्रत्येक नियमाचे चार भाग असतात: एक <strong>व्याप्ती</strong>, एक <strong>ट्रिगर</strong>, एक <strong>लक्ष्य</strong> आणि <strong>प्राप्तकर्त्यांची</strong> यादी.<br><br><strong>व्याप्ती</strong> एकतर <em>डीफॉल्ट</em> (नियम प्रत्येक विभागातील तिकिटांना लागू होतो) किंवा <em>विशिष्ट विभाग</em> (नियम फक्त त्या विभागातील तिकिटांना लागू होतो) असू शकते.<br>तिकिटाचे मूल्यमापन करताना, सिस्टम आधी त्याच्या विभागाशी जुळणारा नियम शोधते &mdash; तो असल्यास तोच नियम लागू होतो आणि डीफॉल्ट दुर्लक्षित केला जातो. विभागासाठी विशिष्ट नियम नसल्यास डीफॉल्ट नियम वापरला जातो. अशा प्रकारे तुम्ही प्रत्येक विभागाला लागू होणारे योग्य डीफॉल्ट ठेवू शकता आणि एखाद्या संघाच्या एस्कलेशन गरजा वेगळ्या असल्यास तिथे अपवाद करू शकता.<br><br><strong>ट्रिगर</strong> म्हणजे एकतर <em>इशारा</em> (तिकिटाने इशारा मर्यादा ओलांडली आहे &mdash; संभाव्य उल्लंघन जवळ येत आहे) किंवा <em>उल्लंघन</em> (तिकिटाने आता त्याचे SLA लक्ष्य ओलांडले आहे &mdash; प्रत्यक्ष उल्लंघन). प्रत्येक वेगळा नियम असतो, त्यामुळे इशारे आणि उल्लंघनांसाठी तुम्ही वेगवेगळ्या लोकांना कळवू शकता.<br><br><strong>लक्ष्य</strong> म्हणजे कोणते SLA घड्याळ पाहायचे &mdash; <em>प्रतिसाद</em>, <em>निराकरण</em> किंवा <em>दोन्ही</em>.<br><br><strong>प्राप्तकर्ते</strong> खालीलपैकी कोणताही संयोग असू शकतो: तिकिटाचा सध्याचा नियुक्त, तिकिटाच्या विभागातील संघांमधील प्रत्येक विश्लेषक, एक नाव दिलेला विश्लेषक आणि/किंवा मोकळ्या ईमेल पत्त्यांची यादी (सामायिक इनबॉक्स किंवा Slack/Teams ईमेल ब्रिजसाठी उपयुक्त).<br><br><strong style="color:var(--warning-text, #92400e);">नियम नाही = ईमेल नाही.</strong> तिकिटाचे उल्लंघन झाले तरीही, तुम्ही किमान एक नियम जोडेपर्यंत काहीही पाठवले जात नाही (सर्वांसाठी संरक्षण मिळवण्यासाठी डीफॉल्ट व्याप्तीची इशारा + उल्लंघन जोडी सुरू करा).',
            'notifs_dedup' => 'प्रत्येक तिकीट प्रत्येक लक्ष्य आणि ट्रिगरसाठी जास्तीत जास्त एकच ईमेल पाठवते &mdash; cron वर्कर आधीच काय पाठवले गेले आहे याचा मागोवा ठेवतो, त्यामुळे तुम्हाला डुप्लिकेट मिळत नाहीत.',
