            'custom_help' => 'उजवीकडे दिसणाऱ्या सिस्टम प्रॉम्प्टच्या शेवटी जोडले जाते. संस्थेनुसार बदलांसाठी (समारोपातील फरक, कंपनीचे नाव, भाषेची पसंती) हे वापरा. कठोर सुरक्षा नियम आणि आउटपुट स्वरूप तरीही प्राधान्याने लागू राहतील.',
