    'help' => [
        'page_title' => 'सर्व्हिस डेस्क - तिकिटे मार्गदर्शक',
        'sidebar_title' => 'मार्गदर्शक',
        'hero_title' => 'तिकिटे मॉड्यूल मार्गदर्शक',
        'hero_sub' => 'IT सपोर्ट विनंत्या एकाच फोल्डर-आधारित इनबॉक्समधून नोंदवा, ट्रॅक करा आणि सोडवा &mdash; सर्व्हिस डेस्क संघांसाठी बनवलेले.',
        'nav' => [
            'overview' => 'आढावा',
            'inbox' => 'इनबॉक्स',
            'working_with_tickets' => 'तिकिटांसह काम करणे',
            'working_faster' => 'जलद काम करणे',
            'comments_attachments' => 'टिप्पण्या &amp; जोडपत्रे',
            'ai_tools' => 'AI साधने',
            'csat' => 'CSAT सर्वेक्षणे',
            'user_management' => 'वापरकर्ता व्यवस्थापन',
            'dashboard' => 'डॅशबोर्ड',
            'calendar_rota' => 'दिनदर्शिका &amp; रोटा',
            'settings' => 'सेटिंग्ज',
            'tips' => 'झटपट टिपा',
            'companies' => 'कंपन्या',
        ],
        'overview' => [
            'heading' => 'आढावा',
            'intro' => 'तिकिटे मॉड्यूल तुमच्या IT सर्व्हिस डेस्कचा गाभा आहे. सपोर्ट विनंत्या, घटना आणि सेवा कार्ये हाताळण्यासाठी ते ईमेल-क्लायंटसारखा परिचित इंटरफेस देते. तिकिटे अंतिम वापरकर्त्यांकडून ईमेलद्वारे किंवा हाताने तयार होऊन येतात आणि विश्लेषक फोल्डर, प्राधान्ये आणि SLA टायमर वापरून त्यावर काम करतात &mdash; जलद IT सपोर्ट देण्यासाठी लागणारे सर्व काही येथे आहे.',
            'card_inbox_title' => 'इनबॉक्स',
            'card_inbox_body' => 'ईमेल क्लायंटवर आधारित फोल्डर-आधारित इनबॉक्स. माझी तिकिटे, नियुक्त नसलेली, सर्व खुली आणि बंद फोल्डर पहा. संपूर्ण तपशील, इतिहास आणि क्रियांसह रीडिंग पेन उघडण्यासाठी कोणत्याही तिकिटावर क्लिक करा.',
            'card_dashboard_title' => 'डॅशबोर्ड',
            'card_dashboard_body' => 'बदलता येण्याजोग्या Chart.js विजेट्सचा वापर करून स्वतःचा डॅशबोर्ड तयार करा. बार, पाय, डोनट आणि लाइन चार्टद्वारे तिकिटांची संख्या, प्रतिसाद वेळ, श्रेणीनुसार विभागणी आणि विश्लेषकांचा कामाचा भार पहा.',
            'card_calendar_title' => 'दिनदर्शिका',
            'card_calendar_body' => 'तिकिटे त्यांच्या तयार केलेल्या, मुदतीच्या किंवा निराकरण झालेल्या तारखांनुसार दिनदर्शिका ग्रिडवर पहा. मुदत उलटून गेलेल्या बाबी पटकन ओळखा आणि तिकिटांचे संपूर्ण चित्र एका नजरेत पाहून आठवड्याचे नियोजन करा.',
            'card_rota_title' => 'रोटा',
            'card_rota_body' => 'विश्लेषकांच्या शिफ्ट आणि ऑन-कॉल रोटा ठरवा. कोणत्याही वेळी कोण उपलब्ध आहे ते पहा, शनिवार-रविवार आणि सुट्ट्यांसाठी कव्हरेजचे नियोजन करा आणि कोणतेही तिकीट दुर्लक्षित राहणार नाही याची खात्री करा.',
        ],
        'inbox' => [
            'heading' => 'इनबॉक्स',
            'intro' => 'इनबॉक्स ही विश्लेषकांची मुख्य कार्यजागा आहे. ती तीन-पेन मांडणी वापरते &mdash; डावीकडे फोल्डर, मध्यभागी तिकिटांची यादी आणि उजवीकडे रीडिंग पेन &mdash; त्यामुळे पान न सोडता तुम्ही वर्गीकरण आणि उत्तर देऊ शकता.',
            'p_live' => '<strong>ते स्वतःहून अद्ययावत राहते.</strong> दर मिनिटाला इनबॉक्स तुमचे मेलबॉक्स तपासतो आणि तुम्हाला दिसणाऱ्या तिकिटांवर काही नवीन आले आहे का ते पाहतो &mdash; पार्श्वभूमीत गोळा केलेला ईमेल, WhatsApp, Telegram, Slack, Teams किंवा Mattermost संदेश, सहकाऱ्याचे उत्तर &mdash; आणि काही आले की, रिफ्रेश बटण दाबल्याप्रमाणेच यादी आणि फोल्डरची संख्या आपोआप रिफ्रेश होते. तुम्ही वाचत असलेले तिकीट आणि तुम्ही लिहीत असलेले कोणतेही उत्तर तसेच राहते.',
            'p_folders' => 'फोल्डर पॅनेल तिकिटांना तार्किक गटांमध्ये मांडते. प्रत्येक फोल्डरमध्ये न वाचलेल्यांची संख्या दिसते, त्यामुळे नवीन काम लगेच ओळखता येते:',
            'field_my' => '<strong>माझी तिकिटे</strong> &mdash; तुम्हाला नियुक्त केलेली तिकिटे. ही तुमची वैयक्तिक रांग आहे आणि दिवसाची सुरुवात करण्यासाठी सर्वोत्तम जागा.',
            'field_unassigned' => '<strong>नियुक्त नसलेली</strong> &mdash; आलेली पण अजून कोणत्याही विश्लेषकाकडे नसलेली तिकिटे. जबाबदारी घेण्यासाठी येथून तिकिटे निवडा.',
            'field_all_open' => '<strong>सर्व खुली</strong> &mdash; मालक कोणीही असला तरी अजून बंद न झालेली प्रत्येक तिकीट. एकूण संख्येवर लक्ष ठेवणारे व्यवस्थापक आणि टीम लीडसाठी उपयुक्त.',
            'field_closed' => '<strong>बंद</strong> &mdash; सोडवलेली तिकिटे. जुने उपाय पाहण्यासाठी किंवा समस्या पुन्हा उघडण्यासाठी येथे शोधा.',
            'field_dept' => '<strong>विभाग फोल्डर</strong> &mdash; विभागानुसार (उदा. IT, HR, Finance) गटबद्ध केलेली तिकिटे. विभाग सेटिंग्जमध्ये ठरवले जातात आणि आपोआप उप-फोल्डर म्हणून दिसतात.',
            'switch_heading' => '<strong>विभाग आणि विश्लेषक गटबद्धतेमध्ये बदल करणे</strong>',
            'switch_body' => 'फोल्डर पॅनेलच्या वरच्या भागातील दोन-बटणांचा छोटा टॉगल एकाच डेटाची दोन दृश्ये बदलतो. <strong>विभाग</strong> गटबद्धता (डीफॉल्ट) प्रत्येक विभागाखाली तिकिटे आणि आत स्थिती उप-फोल्डर दाखवते; <strong>विश्लेषक</strong> गटबद्धता ते उलटते, म्हणजे प्रत्येक वरचा फोल्डर एका विश्लेषकाची वैयक्तिक रांग दर्शवतो आणि आत स्थिती उप-फोल्डर असतात. <strong>नियुक्त नसलेली</strong> फोल्डर प्रत्येक दृश्यात संदर्भानुसार बदलते &mdash; विभाग दृश्यात ते विभाग ठरवलेला नसलेली तिकिटे दाखवते; विश्लेषक दृश्यात ते नियुक्त कोणी नसलेली तिकिटे दाखवते &mdash; त्यामुळे काय उचलायचे आहे ते नेहमी दिसते. तुमची निवड प्रत्येक विश्लेषकासाठी जतन केली जाते, म्हणून प्रत्येक सदस्याला सत्रांमध्ये त्याचे आवडते दृश्य मिळते.',
            'p_actions' => 'तिकिटांच्या यादीच्या वर तुमच्याकडे चार क्रिया बटणे आहेत: तिकीट तयार करण्यासाठी <strong>नवीन</strong>, कीवर्ड, संदर्भ किंवा विनंती करणाऱ्यानुसार तिकिटे शोधण्यासाठी <strong>शोधा</strong>, दिसणारी यादी मर्यादित करण्यासाठी <strong>फिल्टर</strong> आणि सध्याचे फोल्डर पुन्हा लोड करण्यासाठी <strong>रिफ्रेश</strong>.',
            'filter_body' => '<strong>फिल्टर</strong> बटण (गाळणी) फोल्डर आणि यादी दोन्ही एकत्र मर्यादित करते, ती कोणत्याही प्रकारे गटबद्ध असली तरी. <strong>माझी</strong> फक्त तुम्हाला नियुक्त केलेली तिकिटे दाखवते आणि <strong>बंद लपवा</strong> स्थिती बंद म्हणून चिन्हांकित केलेली प्रत्येक तिकीट वगळते. फिल्टर चालू असताना गाळणीवर एक ठिपका दिसतो आणि यादीच्या शीर्षकाशेजारी एक लेबल येते, त्यामुळे तुम्ही सर्व काही पाहत नाही हे तुम्हाला नेहमी कळते. फोल्डर <strong>विश्लेषक</strong> नुसार गटबद्ध असताना तुमचे स्वतःचे फोल्डर त्याऐवजी <strong>माझी तिकिटे</strong> म्हणून सर्वात वर असते. शोधाचा स्वतःचा <strong>बंद तिकिटे समाविष्ट करा</strong> स्विच आहे, जो डीफॉल्टनुसार चालू असतो, कारण शोध हा सहसा जुन्या तिकिटाचा शोध असतो. दोन्ही निवडी फक्त तुमच्यासाठी जतन केल्या जातात.',
            'row_name' => 'प्रत्येक ओळीत तिकिटाचा संदर्भ आणि त्यानंतर एक नाव दिसते. डीफॉल्टनुसार ते <strong>तिकीट नोंदवणाऱ्या व्यक्तीचे</strong> असते आणि तिकिटाच्या संपूर्ण आयुष्यात तेच राहते. तुम्हाला सर्वात अलीकडील संदेश पाठवणारा पाहायचा असेल &mdash; जो तुम्ही उत्तर दिल्यावर तुमचाच मेलबॉक्स बनतो &mdash; तर <strong>सेटिंग्ज &rarr; ओळ प्रदर्शन</strong> मधील <strong>तिकीट क्रमांकाशेजारचे नाव</strong> बदला; तिथे तुम्ही नाव लपवून फक्त संदर्भ ठेवू शकता. ती टॅब तुमची स्वतःची सेटिंग आहे: ती इतर कोणासाठीही काहीही बदलत नाही.',
            'tip' => 'यादीतील कोणत्याही तिकिटावर क्लिक केल्यावर ते रीडिंग पेनमध्ये लोड होते. तिथून तुम्ही फील्ड अद्यतनित करू शकता, टिप्पण्या जोडू शकता, ईमेलने उत्तर देऊ शकता किंवा फाइल्स जोडू शकता &mdash; इनबॉक्स सोडून कुठेही न जाता.',
        ],
        'faster' => [
            'heading' => 'जलद काम करणे',
            'intro' => 'व्यस्त सकाळ सोपी करणाऱ्या चार गोष्टी: जतन केलेली उत्तरे, एकाच वेळी अनेक तिकिटांवर कृती आणि संभाषणे योग्य जागी ठेवणे.',
            'templates_heading' => 'तयार उत्तरे',
            'templates_body' => 'तुम्ही तीच काही उत्तरे सतत पाठवता. एक उत्तर एकदा लिहा, मग उत्तर विंडोच्या खालच्या डावीकडील <strong>टेम्पलेट्स</strong> वर क्लिक करून ते तुमच्या कर्सरच्या जागी टाका &mdash; तुम्ही आधी टाइप केलेले बदलत नाही, त्यात भर पडते. टेम्पलेट्स रिच टेक्स्ट असतात आणि स्वयंचलित ईमेलप्रमाणेच <code>[merge_code]</code> प्लेसहोल्डर्स वापरता येतात, म्हणून <code>[requester_first_name]</code> टाकताना खरे नाव बनते.',
            'templates_team' => '<strong>संघ टेम्पलेट्स</strong> &mdash; सर्वांसोबत शेअर केलेले, सेटिंग्ज &rarr; उत्तर टेम्पलेट्स मध्ये तयार केलेले.',
            'templates_mine' => '<strong>तुमचे स्वतःचे</strong> &mdash; <em>मसुदा टेम्पलेट म्हणून जतन करा</em> सह मसुदा जतन करा. फक्त तुमच्यासाठी खाजगी आणि कोणत्याही परवानगीची गरज नाही.',
            'templates_tip' => 'टेम्पलेटला त्याच्या शब्दांवरून नाही तर प्रसंगावरून नाव द्या ("प्रिंटर ऑफलाइन &mdash; पहिल्या पायऱ्या"). सकाळी 9 वाजता तुम्ही तेच शोधत असाल.',
            'select_heading' => 'अनेक तिकिटे निवडणे',
            'select_body' => 'तिकिटांची यादी Outlook किंवा File Explorer सारखी चालते. चेकबॉक्स नाहीत.',
            'key_click' => 'क्लिक',
            'key_click_d' => 'एक निवडा आणि उघडा',
            'key_ctrl' => 'Ctrl+क्लिक',
            'key_ctrl_d' => 'बाकीची तशीच ठेवून एक जोडा किंवा काढा',
            'key_shift' => 'Shift+क्लिक',
            'key_shift_d' => 'तुम्ही शेवटी क्लिक केलेल्या जागेपासून संपूर्ण गट निवडा',
            'key_kb' => 'कीबोर्ड',
            'key_kb_d' => 'हलण्यासाठी बाण, वाढवण्यासाठी Shift+बाण, विखुरलेली तिकिटे निवडण्यासाठी Ctrl+बाण आणि Space, सर्वांसाठी Ctrl+A, निवड साफ करण्यासाठी Escape',
            'select_actions' => 'अनेक निवडलेली असताना, त्या सर्वांसाठी एकाच वेळी स्थिती, प्राधान्य, विभाग, प्रकार किंवा नियुक्त ठरवण्यासाठी <strong>त्यापैकी कोणत्यावरही राइट-क्लिक करा</strong> &mdash; किंवा संपूर्ण संच एखाद्या फोल्डरवर ड्रॅग करा. अनेक निवडलेली असताना स्क्रीन काय दाखवते ही तुमची निवड आहे, अकाउंट मेनूमधील प्राधान्यांमध्ये.',
            'select_tip' => 'तुमच्या निवडीत <em>नसलेल्या</em> तिकिटावर राइट-क्लिक केल्यास निवड साफ होते आणि फक्त तेच तिकीट लक्ष्य बनते. हे जाणीवपूर्वक आहे &mdash; तुम्ही सोडून दिलेल्या संचावर तुमच्याकडून कधीच कृती होणार नाही.',
            'merge_heading' => 'डुप्लिकेट विलीन करणे',
            'merge_body' => 'दोन जणांनी एकाच खंडनाची तक्रार केली? तिकिटे निवडा, राइट-क्लिक करा, <strong>विलीन करा</strong>. संभाषणे एकत्र येतात आणि तुम्ही AI प्रदाता कॉन्फिगर केला असेल तर FreeITSM प्रत्येकाने काय विचारले आणि आधीच काय केले गेले याचा छोटा सारांश लिहिते, त्यामुळे ते हाती घेणाऱ्याला चार थ्रेड वाचावे लागत नाहीत.',
            'merge_tip' => 'काहीही हटवले जात नाही. विलीन केलेले तिकीट आपला संदर्भ ठेवते, शोधण्यायोग्य राहते, ते कुठे गेले ते दाखवते &mdash; आणि त्याबद्दलच्या जुन्या ईमेलला उत्तर देणाऱ्या ग्राहकाचे उत्तर तरीही तुमच्यापर्यंत पोहोचते.',
            'split_heading' => 'तिकीट विभाजित करणे',
            'split_body' => 'याच्या उलट काम. संभाषणाच्या मध्येच कोणी दुसरी, असंबंधित गोष्ट मांडली तर त्या संदेशावर <strong>विभाजित करा</strong> वर क्लिक करा (किंवा संदेशाच्या हेडरवर राइट-क्लिक करा). तो नवीन तिकिटात जातो, हवे असल्यास त्यानंतरचे प्रत्येक संदेशही सोबत घेऊन, आणि मूळ तिकिटावर ते कुठे गेले दाखवणारी खूण राहते.',
            'split_tip' => 'नवीन तिकिटाला योग्य विषय द्या. तो डीफॉल्टनुसार ‘हलवलेला संदेश&rsquo; याचा विषय असतो, जो सहसा <em>जुन्या</em> समस्येचा "RE:" असतो.',
            'undo_heading' => 'मत बदलले',
            'undo_body' => 'दोन्ही तिकिटावरील बॅनरमधून पूर्ववत करता येतात. नवीन तिकिटावर कोणी उत्तर दिले, टीप जोडली किंवा वेळ नोंदवला की <strong>विभाजन</strong> पूर्ववत करणे नाकारले जाते &mdash; काय आड येत आहे ते तुम्हाला नेमके सांगितले जाते. <strong>विलीनीकरण</strong> पूर्ववत केल्यास तिकिटाला त्याचे संदेश, टिपा आणि नोंदवलेला वेळ परत मिळतात आणि ते जसे होते तसेच पुन्हा उघडते, पण विलीनीकरणानंतर दुसऱ्या तिकिटावर लिहिलेली उत्तरे तिथेच राहतात.',
        ],
        'working' => [
            'heading' => 'तिकिटांसह काम करणे',
            'intro' => 'प्रत्येक सपोर्ट विनंती एका जीवनचक्रातून जाते: ती तयार होते, तिचे वर्गीकरण होते, त्यावर काम होते आणि शेवटी ती सोडवली जाते. सुरुवातीच्या नोंदीपासून बंद करण्यापर्यंत प्रत्येक टप्पा कार्यक्षमतेने हाताळण्यासाठी तिकिटे मॉड्यूल तुम्हाला साधने देते.',
            'creating_heading' => '<strong>नवीन तिकीट तयार करणे</strong>',
            'step1' => '<strong>नवीन क्लिक करा</strong> &mdash; इनबॉक्स टूलबारमधून नवीन तिकीट मॉडल उघडा. विनंती करणाऱ्याचे नाव आणि ईमेल पत्ता प्रविष्ट करा जेणेकरून त्यांना अद्यतने मिळतील.',
            'step2' => '<strong>विषय ठरवा</strong> &mdash; समस्येचा स्पष्ट, संक्षिप्त सारांश लिहा. तो तिकिटांच्या यादीत आणि अंतिम वापरकर्त्याला पाठवलेल्या कोणत्याही ईमेल सूचनांमध्ये दिसतो.',
            'step3' => '<strong>विभाग, प्रकार आणि प्राधान्य निवडा</strong> &mdash; योग्य विभाग, तिकिटाचा प्रकार (उदा. घटना, सेवा विनंती) आणि प्राधान्य स्तर निवडा. ही फील्ड SLA टायमर आणि राउटिंग नियम चालवतात.',
            'step4' => '<strong>वर्णन जोडा</strong> &mdash; रिच टेक्स्ट एडिटर वापरून समस्येचे संपूर्ण तपशील द्या. निराकरण करणाऱ्या विश्लेषकाला लागणाऱ्या पुनरुत्पादनाच्या पायऱ्या, त्रुटी संदेश आणि कोणताही संबंधित संदर्भ समाविष्ट करा.',
            'step5' => '<strong>जतन करा</strong> &mdash; तिकीट एका अद्वितीय संदर्भ क्रमांकासह तयार होते आणि योग्य फोल्डरमध्ये दिसते. SLA घड्याळ प्राधान्यानुसार लगेच सुरू होते.',
            'editing_heading' => '<strong>तिकिटे संपादित करणे आणि व्यवस्थापित करणे</strong>',
            'editing_body' => 'तिकीट तयार झाल्यावर तुम्ही रीडिंग पेनमधून कोणतेही फील्ड अद्यतनित करू शकता. मुख्य फील्ड अशी आहेत:',
            'card_status_title' => 'स्थिती',
            'card_status_body' => 'तिकिटाच्या जीवनचक्राचा मागोवा घ्या: नवीन, खुले, प्रगतीत, प्रलंबित, निराकरण झाले, बंद',
            'card_priority_title' => 'प्राधान्य',
            'card_priority_body' => 'निकड आणि परिणाम ठरवा: गंभीर, जास्त, मध्यम, कमी. प्रत्येक स्तराचे स्वतःचे SLA लक्ष्य असते',
            'card_category_title' => 'श्रेणी',
            'card_category_body' => 'समस्येचा प्रकार वर्गीकृत करा: हार्डवेअर, सॉफ्टवेअर, नेटवर्क, प्रवेश, सामान्य. अहवालांसाठी उपयुक्त',
            'card_analyst_title' => 'नियुक्त विश्लेषक',
            'card_analyst_body' => 'तिकीट सोडवण्याची जबाबदारी असलेली व्यक्ती. पुनर्नियुक्ती क्रियाकलाप नोंदीत नोंदवली जाते',
            'card_enduser_title' => 'अंतिम वापरकर्ता',
            'card_enduser_body' => 'विनंती नोंदवणारी व्यक्ती. विद्यमान वापरकर्ता रेकॉर्डशी जोडण्यासाठी नाव किंवा ईमेलने शोधा',
            'card_dept_title' => 'विभाग',
            'card_dept_body' => 'तिकिटे योग्य संघाकडे पाठवा. विभाग फोल्डर गटबद्धता आणि डॅशबोर्ड फिल्टर चालवतात',
            'flow_new' => 'नवीन',
            'flow_in_progress' => 'प्रगतीत',
            'flow_resolved' => 'निराकरण झाले',
            'flow_closed' => 'बंद',
            'triage_heading' => '<strong>ड्रॅग आणि ड्रॉपने वर्गीकरण</strong>',
            'triage_body' => 'वर्गीकरणासाठी तिकीट उघडावे लागत नाही. तिकिटांच्या यादीतील कोणतीही ओळ एखाद्या फोल्डरवर ड्रॅग करा आणि फील्ड एका हालचालीत अद्यतनित करा:',
            'triage_dept' => '<strong>विभाग दृश्य</strong> &mdash; पुन्हा नेमण्यासाठी विभाग फोल्डरवर ड्रॉप करा, दोन्ही एकदम अद्यतनित करण्यासाठी विभागाखालील स्थिती उप-फोल्डरवर ड्रॉप करा, विभाग साफ करण्यासाठी <strong>नियुक्त नसलेली</strong> वर ड्रॉप करा.',
            'triage_analyst' => '<strong>विश्लेषक दृश्य</strong> &mdash; त्या विश्लेषकाला मालक म्हणून नियुक्त करण्यासाठी विश्लेषकाच्या फोल्डरवर ड्रॉप करा (रीडिंग पेनमधील मालक फील्ड जुळलेले राहण्यासाठी <code>assigned_analyst_id</code> आणि <code>owner_id</code> दोन्ही सेट होतात), दोन्ही अद्यतनित करण्यासाठी स्थिती उप-फोल्डरवर ड्रॉप करा, नियुक्त साफ करण्यासाठी <strong>नियुक्त नसलेली</strong> वर ड्रॉप करा.',
            'triage_spring' => '<strong>स्प्रिंग-लोडेड फोल्डर</strong> &mdash; ड्रॅग करताना बंद फोल्डरवर थांबल्यास ते आपोआप उघडते (Outlook प्रमाणे), त्यामुळे आधी ड्रॉप न करता आतील कोणतीही स्थिती गाठता येते.',
            'fullscreen_heading' => '<strong>फुल-स्क्रीन दृश्य</strong>',
            'fullscreen_body' => 'एकाच तिकिटावर लक्ष केंद्रित करायचे असेल तेव्हा &mdash; लांब संभाषण, गुंतागुंतीचा बदल, तपशीलवार उत्तराचा मसुदा &mdash; फुल-स्क्रीन दृश्यावर जा. फोल्डर यादी आणि तिकिटांची यादी नाहीशी होते, संभाषण उपलब्ध रुंदी व्यापते आणि प्रॉपर्टीज (विभाग, प्रकार, स्थिती, उगम, First Time Fix, IT प्रशिक्षण, मालक) उजवीकडील उभ्या साइडबारमध्ये जातात.',
            'fullscreen_max' => '<strong>मोठे करा चिन्ह</strong> &mdash; तिकिटाच्या विषय ओळीच्या उजव्या टोकाला असलेले छोटे चिन्ह. फुल-स्क्रीनमध्ये जाण्यासाठी क्लिक करा; 3-पेन मांडणीत परतण्यासाठी पुन्हा क्लिक करा.',
            'fullscreen_dbl' => '<strong>ओळीवर डबल-क्लिक करा</strong> &mdash; यादीतील कोणत्याही तिकिटावर डबल-क्लिक करून ते थेट फुल-स्क्रीनमध्ये उघडा, Outlook प्रमाणे "हे खरोखर उघडा" अशी कृती.',
            'fullscreen_sticks' => '<strong>निवडी बदलल्या तरी टिकते</strong> &mdash; एकदा फुल-स्क्रीनमध्ये गेलात की पुढच्या तिकिटावर गेल्यावरही तुम्ही तिथेच राहता. कोणतेही तिकीट निवडलेले नसताना पान पुन्हा लोड (F5) केल्यास डीफॉल्ट 3-स्तंभ मांडणी परत येते, त्यामुळे फोल्डर यादी लपलेल्या अवस्थेत तुम्ही अडकू शकत नाही.',
            'rightclick_heading' => '<strong>झटपट क्रियांसाठी राइट-क्लिक</strong>',
            'rightclick_body' => 'संदर्भ मेनू उघडण्यासाठी यादीतील कोणत्याही तिकिटावर राइट-क्लिक करा. मेनूच्या वरच्या भागात तिकिटाचा संदर्भ दिसतो, म्हणजे तुम्ही कशावर कृती करत आहात ते कळते, आणि प्रत्येक कृती रीडिंग पेनमध्ये सध्या उघडलेले काय आहे ते <em>न बदलता</em> राइट-क्लिक केलेल्या तिकिटावर होते &mdash; तिकीट A वाचत असताना तुमची जागा न गमावता तिकीट B चे वर्गीकरण करायचे असेल तेव्हा उपयुक्त.',
            'rightclick_status' => '<strong>स्थिती ठरवा &rarr;</strong> &mdash; प्रत्येक सक्रिय स्थिती तिच्या रंगाच्या नमुन्यासह दाखवणारा फ्लायआउट सबमेनू. तुम्ही उघडलेल्या तिकिटावरच राइट-क्लिक करत असाल तर सध्याच्या मूल्याशेजारी टिक दिसते. निवड केल्यावर तिकीट लगेच अद्यतनित होते, ऑडिट-ट्रेल नोंद लिहिली जाते, फोल्डर संख्या रिफ्रेश होते आणि लागू असल्यास रीडिंग पेनचा स्थिती ड्रॉपडाउन जुळवला जातो.',
            'rightclick_priority' => '<strong>प्राधान्य ठरवा &rarr;</strong> &mdash; तोच फ्लायआउट नमुना, सक्रिय प्राधान्यांच्या यादीतून घेतलेला आणि प्रत्येकाचा रंग नमुना म्हणून. पहिली ओळ ही नियुक्ती साफ करण्यासाठी <em>(प्राधान्य नाही)</em> पर्याय आहे (प्राधान्य रिकामे असू शकते).',
            'rightclick_assign' => '<strong>यांना नियुक्त करा &rarr;</strong> &mdash; लोड केलेल्या प्रत्येक विश्लेषकाला राखाडी आद्याक्षर चिपसह दाखवणारा सबमेनू, आणि साफ करण्यासाठी सर्वात वर <em>(नियुक्त नाही)</em> ओळ. निवड केल्यावर <code>assigned_analyst_id</code> आणि <code>owner_id</code> दोन्ही सेट होतात, म्हणून रीडिंग पेनचे मालक फील्ड जुळलेले राहते.',
            'rightclick_cmdb' => '<strong>CMDB ऑब्जेक्ट लिंक करा&hellip;</strong> &mdash; टाइप करताना शोधणारा पिकर उघडतो. लिंक करण्यासाठी निकालावर क्लिक करा, मग निवडत राहा &mdash; इनपुट साफ होते आणि पुढच्यासाठी पुन्हा फोकस घेते, आणि मॉडलमधील "अलीकडे लिंक केलेले" नोंद हिरव्या टिक पुष्टींची तुमची चालू यादी दाखवते.',
            'rightclick_time' => '<strong>वेळ नोंदवा&hellip;</strong> &mdash; मिनिटे + तारीख-वेळ पिकर (डीफॉल्ट "आत्ता", त्यामुळे तुम्ही मागची तारीखही देऊ शकता) + पर्यायी टिपांचा बॉक्स असलेला मॉडल उघडतो.',
            'rightclick_phone' => '<strong>फोनवर</strong>, तोच मेनू फुल-स्क्रीन पॅनेल म्हणून उघडण्यासाठी तिकिटावर अर्धा सेकंद दाबून ठेवा. अधिक पर्याय असलेली निवड &mdash; स्थिती ठरवा, प्राधान्य ठरवा, यांना नियुक्त करा &mdash; त्या पर्यायांकडे सरकते, आणि परतण्यासाठी <strong>मागे</strong> असते.',
            'rightclick_tip' => 'संदर्भ मेनूमधून तुम्ही ज्या तिकिटावर कृती करत आहात तेच रीडिंग पेनमध्ये उघडलेले असेल, तर मॉडल बंद झाल्यावर तिथला संबंधित विभाग (स्थिती / प्राधान्य ड्रॉपडाउन, CMDB ऑब्जेक्ट, वेळ नोंदी) आपोआप रिफ्रेश होतो, त्यामुळे UI जुळलेले राहते.',
            'time_heading' => '<strong>वेळ नोंदवणे</strong>',
            'time_body' => 'तिकिटावर घालवलेला वेळ रीडिंग पेनमधील समर्पित <strong>वेळ नोंदी</strong> विभागात नोंदवला जातो, जो लिंक केलेल्या CMDB ऑब्जेक्ट पॅनेल आणि टिपा पॅनेलच्या मध्ये असतो. हेडरमध्ये चालू एकूण दिसतो (उदा. "एकूण 2h 30m") आणि खालील प्रत्येक नोंदीत घालवलेला वेळ, विश्लेषक, तारीख आणि तुम्ही जोडलेल्या टिपा दिसतात.',
            'time_step1' => '<strong>इनलाइन फॉर्म</strong> &mdash; संख्या इनपुटमध्ये घालवलेली मिनिटे टाइप करा, टिपा इनपुटमध्ये पर्यायी छोटे वर्णन लिहा आणि <strong>जोडा</strong> वर क्लिक करा. नवीन नोंद तुमचे नाव आणि सध्याच्या वेळेच्या शिक्क्यासह यादीच्या सर्वात वर लगेच दिसते.',
            'time_step2' => '<strong>राइट-क्लिकने मागची तारीख द्या</strong> &mdash; आधी नोंदवायला विसरलेला वेळ नोंदवायचा असेल तर यादीतील तिकिटावर राइट-क्लिक करा आणि <strong>वेळ नोंदवा&hellip;</strong> निवडा. मॉडलमध्ये तारीख-वेळ पिकर असतो, म्हणून काम प्रत्यक्ष झालेल्या वेळेचा शिक्का तुम्ही नोंदीवर देऊ शकता.',
            'time_step3' => '<strong>तुमच्या स्वतःच्या नोंदी हटवा</strong> &mdash; तुम्ही नोंदवलेल्या नोंदींशेजारी छोटे &times; बटण दिसते. सॉफ्ट-डिलीट करण्यासाठी त्यावर क्लिक करा (आणि पुष्टी करा) &mdash; ऑडिटसाठी ओळ <code>is_active = 0</code> सह डेटाबेसमध्ये राहते, पण यादीतून नाहीशी होते. इतर विश्लेषकांच्या नोंदी तुम्ही हटवू शकत नाही.',
            'time_tip1' => 'वेळ साध्या मिनिटांत (45 min, 90 min इ.) साठवला जातो आणि UI मध्ये <code>45m</code> किंवा <code>1h 30m</code> म्हणून दिसतो &mdash; छोट्या दुरुस्त्यांसाठी पुरेसा सूक्ष्म, दशांश-तासांच्या राउंडिंगचा त्रास नाही.',
            'time_tip2' => 'प्रत्येक फील्ड बदल तिकिटाच्या क्रियाकलाप नोंदीत नोंदवला जातो. कोणी काय आणि केव्हा बदलले ते तुम्हाला नेहमी दिसते, जे ऑडिट अनुपालनासाठी आणि विश्लेषकांमधील हस्तांतरणासाठी आवश्यक आहे.',
        ],
        'comments' => [
            'heading' => 'टिप्पण्या आणि जोडपत्रे',
            'intro' => 'क्रियाकलाप नोंद हा प्रत्येक तिकिटाचा गाभा आहे. केलेली प्रत्येक कृती &mdash; टिप्पण्या, फील्डमधील बदल, पाठवलेले ईमेल आणि जोडलेल्या फाइल्स &mdash; कालक्रमानुसार टाइमलाइनमध्ये नोंदवली जाते, आणि त्यातून सपोर्ट विनंतीची संपूर्ण कहाणी समजते.',
            'adding_heading' => '<strong>टिप्पण्या जोडणे</strong>',
            'step1' => '<strong>तिकीट उघडा</strong> &mdash; इनबॉक्समधील कोणत्याही तिकिटावर क्लिक करा, त्याचे रीडिंग पेन लोड होईल. संपूर्ण क्रियाकलाप नोंद आणि तळाशी असलेला टिप्पणी बॉक्स पाहण्यासाठी खाली स्क्रोल करा.',
            'step2' => '<strong>तुमची नोंद लिहा</strong> &mdash; टिप्पणी एडिटर उघडण्यासाठी नोंद जोडा बटण वापरा. नोंदी डीफॉल्टनुसार अंतर्गत असतात आणि फक्त सर्व्हिस डेस्कवरील विश्लेषकांना दिसतात.',
            'step3' => '<strong>ईमेलने उत्तर द्या किंवा फॉरवर्ड करा</strong> &mdash; अंतिम वापरकर्त्याला किंवा तृतीय पक्षाला संदेश पाठवण्यासाठी उत्तर द्या किंवा फॉरवर्ड करा या कृती वापरा. ईमेल पाठवलेल्या संदेशाच्या मजकुरासह क्रियाकलाप नोंदीत नोंदवला जातो.',
            'files_heading' => '<strong>फाइल जोडपत्रे</strong>',
            'files_body' => 'स्क्रीनशॉट, लॉग, दस्तऐवज किंवा कोणतीही आधारभूत फाइल थेट तिकिटाला जोडा. फाइल्स जोडपत्र ड्रॉप झोनमध्ये ड्रॅग करता येतात किंवा फाइल ब्राउझर वापरून निवडता येतात. जोडपत्रे सर्व्हरवर साठवली जातात आणि तिकिटाच्या क्रियाकलाप नोंदीशी जोडली जातात, त्यामुळे काहीही हरवत नाही.',
            'audit_heading' => '<strong>ऑडिट नोंद</strong>',
            'audit_body' => 'क्रियाकलाप नोंद विश्लेषकाच्या हस्तक्षेपाशिवाय प्रत्येक कृती आपोआप नोंदवते. प्राधान्य मध्यम वरून जास्त केले जाते तेव्हा जुने आणि नवीन दोन्ही मूल्ये नोंदवली जातात. तिकीट दुसऱ्याला नेमले जाते तेव्हा मागील आणि नवीन दोन्ही विश्लेषक नोंदवले जातात. यामुळे ITIL ऑडिट आवश्यकता पूर्ण करणारा आणि छेडछाड करता न येणारा संपूर्ण इतिहास तयार होतो, आणि तिकिटे कशी हाताळली जात आहेत हे व्यवस्थापकांना समजायला मदत होते.',
            'tip' => 'ईमेलने उत्तर देताना तुम्ही त्याच कृतीत Cc प्राप्तकर्ते जोडू शकता आणि फाइल्स जोडू शकता. संपूर्ण ईमेल संभाषण तिकिटाच्या क्रियाकलाप नोंदीत थ्रेड केले जाते, त्यामुळे सर्व संवाद एकाच ठिकाणी राहतो.',
        ],
        'ai' => [
            'heading' => 'AI साधने',
            'intro' => 'तिकीट कार्यप्रवाहात Claude वर चालणारी दोन वैशिष्ट्ये आहेत: <strong>Reply Cleanup</strong> कच्च्या मसुद्याचे योग्य स्वरूपातील ईमेलमध्ये रूपांतर करते, आणि <strong>AI ला विचारा</strong> तिकिटाच्या संदर्भाचा वापर करून ज्ञान आधारात नैसर्गिक भाषेत शोध घेते.',
            'cleanup_heading' => '<strong>Reply Cleanup &mdash; उत्तर एडिटरमधील ✨ बटण</strong>',
            'cleanup_body' => 'उत्तरात पटकन कच्चा मसुदा लिहा (किंवा फक्त मुद्दे, जसे *"प्रिंट सेवा रीस्टार्ट करायची आहे, त्यांच्यासाठी स्क्रीनशॉट घ्या"*) आणि <strong>✨ Cleanup</strong> बटणावर क्लिक करा. Claude ते योग्य स्वरूपातील ईमेल म्हणून पुन्हा लिहिते &mdash; विनंती करणाऱ्याच्या नावाने <em>Dear [name],</em> अभिवादन जोडते, व्याकरण दुरुस्त करते, ठरवलेला सूर लागू करते आणि <em>Kind regards,</em> ने समाप्त करते. प्रॉम्प्ट असा बंदिस्त केला आहे की ते तांत्रिक तपशील स्वतः रचणार नाही, खोटी माफी मागणार नाही आणि तुम्ही लिहिलेल्यापेक्षा मजकूर वाढवणार नाही.',
            'cleanup_streams' => '<strong>थेट स्ट्रीम होते</strong> &mdash; Claude तयार करत असतानाच पुन्हा लिहिलेला मजकूर एडिटरमध्ये दिसतो (स्पिनरसमोर थांबावे लागत नाही).',
            'cleanup_undo' => '<strong>३० सेकंदांसाठी पूर्ववत लिंक</strong> &mdash; Claude ने पुन्हा लिहिलेले बिघडवले तर, पुन्हा लिहून झाल्यानंतर ३० सेकंद एडिटरखाली एक छोटी <em>पूर्ववत करा</em> लिंक दिसते आणि ती मूळ मसुदा परत आणते.',
            'cleanup_tone' => '<strong>प्रत्येक सूरासाठी</strong> &mdash; <strong>सेटिंग्ज &rarr; Reply Cleanup</strong> मध्ये तीन सूर प्रीसेट कॉन्फिगर करता येतात: <em>मैत्रीपूर्ण</em> (डीफॉल्ट), <em>औपचारिक</em>, <em>संक्षिप्त</em>. तुमच्या संघाच्या शैलीला जुळणारा निवडा.',
            'cleanup_key' => '<strong>स्वतःची API key</strong> &mdash; RFP / Knowledge / Workflow AI वैशिष्ट्यांपेक्षा वेगळी Anthropic key, त्यामुळे तिचा वापर Anthropic बिलिंग डॅशबोर्डवर स्वतंत्र ओळ म्हणून दिसतो. <strong>सेटिंग्ज &rarr; Reply Cleanup</strong> मध्ये कॉन्फिगर करा.',
            'cleanup_tip' => '"मी हे करून पाहिले, कृपया X करून पहा" अशा नेहमीच्या उत्तरांसाठी Cleanup सर्वोत्तम आहे. लांब आणि सूक्ष्म संदेश तुम्ही स्वतः लिहिलेले बरे &mdash; AI रचनेत उत्तम आहे, पण तुमचे विशिष्ट वातावरण त्याला माहीत नसते.',
            'ask_heading' => '<strong>AI ला विचारा &mdash; तिकीट टूलबारमधील 🤖 बटण</strong>',
            'ask_body' => 'उघड्या तिकिटाचा विषय, मजकूर आणि रीडिंग पेनचा संदर्भ माहीत असलेला स्लाइड-इन चॅट पॅनेल उघडण्यासाठी तिकीट टूलबारमधील <strong>AI ला विचारा</strong> बटणावर (🤖) क्लिक करा. त्याला *"हे आपण आधी पाहिले आहे का?"* किंवा *"या त्रुटीवर नेहमीचा उपाय काय?"* असे प्रश्न विचारा; तो <a href="../knowledge/" style="color:#0078d4;">ज्ञान</a> आधारात अर्थानुसार (Claude + OpenAI embeddings द्वारे) शोध घेतो आणि संबंधित लेख व ते उघडण्यासाठी थेट लिंक देऊन उत्तर देतो.',
            'ask_context' => '<strong>संदर्भ-जागरूक</strong> &mdash; तुम्ही कोणते तिकीट पाहत आहात हे पॅनेलला माहीत असते, त्यामुळे तुम्ही सामान्य प्रश्न विचारू शकता आणि तो योग्य संदर्भ स्वतः ओळखतो.',
            'ask_linked' => '<strong>जोडलेले लेख</strong> &mdash; सूचना क्लिक करण्यायोग्य असतात आणि जुळणारा ज्ञान लेख नवीन टॅबमध्ये उघडतात.',
            'ask_shared' => '<strong>ज्ञान मॉड्यूलशी सामायिक</strong> &mdash; AI, Knowledge AI शोधाचीच key आणि मॉडेल वापरतो, त्यामुळे एकदा कॉन्फिगर केल्यावर दोन्ही चालतात. सेटअप तपशीलांसाठी ज्ञान मॉड्यूलची मदत पहा.',
        ],
        'csat' => [
            'heading' => 'ग्राहक समाधान सर्वेक्षणे (CSAT)',
            'intro' => 'तिकिटाचे निराकरण झाल्यावर विनंती करणाऱ्याला १&ndash;५ समाधान सर्वेक्षण ईमेल करा, लॉगिन न लागणाऱ्या लँडिंग पेजवर प्रतिसाद मिळवा, आणि स्वतंत्र विश्लेषण पानावर प्रत्येक विश्लेषकाचा कल मागोवा घ्या.',
            'modes_heading' => '<strong>दोन ट्रिगर मोड &mdash; एक निवडा</strong>',
            'mode_auto' => '<strong>बंद करताना आपोआप</strong> &mdash; तिकीट कोणत्याही बंद स्थितीत गेले की सर्वेक्षण आपोआप रांगेत टाकले जाते. विश्लेषकाला काहीही करावे लागत नाही &mdash; निराकरणामुळेच सर्वेक्षण सुरू होते.',
            'mode_manual' => '<strong>फक्त मॅन्युअल</strong> &mdash; अभिप्राय मागायचा असेल तेव्हा विश्लेषक तिकीट टूलबारमधील ⭐ <strong>अभिप्राय</strong> बटणावर क्लिक करतो. प्रत्येक तिकिटासाठी अभिप्राय मागायचा की नाही हे तुम्हाला स्वतः ठरवायचे असेल तेव्हा उपयुक्त.',
            'mode_off' => '<strong>बंद</strong> &mdash; वैशिष्ट्य अक्षम; कोणतेही सर्वेक्षण ईमेल पाठवले जात नाहीत.',
            'modes_choose' => '<strong>तिकिटे &rarr; सेटिंग्ज &rarr; CSAT</strong> मध्ये निवडा. मॅन्युअल बटण <em>auto</em> मोडमध्येही चालते &mdash; गरज असल्यास विश्लेषक आधीच सर्वेक्षण झालेल्या तिकिटावर पुन्हा अभिप्राय मागू शकतात.',
            'template_heading' => '<strong>ईमेल टेम्पलेट</strong>',
            'template_body' => 'सर्वेक्षण ईमेलचा मजकूर विद्यमान <strong>ईमेल टेम्पलेट्स</strong> टॅबमधून येतो &mdash; इव्हेंट <strong>CSAT सर्वेक्षण</strong> (<em>तिकीट नेमले</em> / <em>तिकीट बंद केले</em> सोबतचा नवीन इव्हेंट) असलेले टेम्पलेट तयार करा आणि रेटिंग URL जिथे दिसावी तिथे <code>[csat_link]</code> मर्ज कोड घाला. मानक मर्ज कोड (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) नेहमीप्रमाणे उपलब्ध आहेत.',
            'template_tip' => 'सक्रिय CSAT टेम्पलेट नसल्यास, <em>अभिप्राय</em> बटण स्पष्ट त्रुटी देऊन नकार देते आणि ऑटो-ट्रिगर शांतपणे वगळले जाते &mdash; त्यामुळे निरुपयोगी सर्वेक्षण लिंक कधीच तयार होत नाहीत.',
            'survey_heading' => '<strong>सर्वेक्षण पान</strong>',
            'survey_body' => 'विनंती करणारा ईमेलमधील लिंकवर क्लिक करतो आणि १&ndash;५ निवडक व पर्यायी टिप्पणी बॉक्स असलेल्या लॉगिनविना पानावर पोहोचतो. <strong>सेटिंग्ज &rarr; CSAT</strong> मध्ये दोन दृश्य शैली कॉन्फिगर करता येतात:',
            'survey_stars' => '<strong>तारे</strong> &mdash; क्लासिक होव्हरवर भरत जाणारे वर्तन. तिसऱ्या ताऱ्यावर होव्हर केल्यास #१+#२+#३ सोनेरी रंगाने भरतात. निश्चित करण्यासाठी क्लिक करा.',
            'survey_emojis' => '<strong>इमोजी</strong> &mdash; ५ चेहरे 😡 🙁 😐 🙂 😀 ४०% अपारदर्शकतेसह करड्या रंगात सुरू होतात; होव्हर केलेला किंवा निवडलेला पूर्ण रंगात १.२५&times; आकारात परत येतो. निश्चित करण्यासाठी क्लिक करा.',
            'survey_store' => 'दोन्ही मोड तीच १&ndash;५ संख्या साठवतात, त्यामुळे कोणतीही शैली वापरली तरी डॅशबोर्ड आणि सरासरी सारखीच चालतात. सर्वेक्षण URL एकदाच वापरता येते &mdash; वापरकर्त्याने सबमिट केल्यावर तीच लिंक पुन्हा सबमिशन नाकारते.',
            'chat_heading' => '<strong>चॅट ग्राहकांना त्यांच्याच चॅटमध्ये विचारणे</strong>',
            'chat_body' => '<strong>चॅट ग्राहकांना त्यांच्याच चॅटमध्ये विचारा</strong> निवडले असल्यास, WhatsApp, Telegram, Slack, Microsoft Teams किंवा Mattermost वर लिहिलेल्या ग्राहकाला ईमेलऐवजी त्याच चॅटमध्ये विचारले जाते &mdash; Telegram, Teams आणि Mattermost वर पाच बटणे, इतरत्र &ldquo;एकाच अंकाने उत्तर द्या&rdquo;. त्यांचे उत्तर ईमेल केलेल्या सर्वेक्षणाप्रमाणेच त्याच निकालांत जाते.',
            'chat_rules' => 'WhatsApp वर फक्त त्याची २४ तासांची उत्तर विंडो उघडी असतानाच विचारले जाते; ती बंद असल्यास, किंवा चॅट संदेश पाठवता न आल्यास, त्याऐवजी ईमेल सर्वेक्षण वापरले जाते. अंक फक्त प्रश्नानंतर लगेच आला तरच रेटिंग मानला जातो &mdash; त्याच चॅटमध्ये, आठवड्याच्या आत, आणि ग्राहकाने दुसरे काही लिहिण्यापूर्वी &mdash; म्हणून विश्लेषकाच्या प्रश्नाच्या उत्तरातील &ldquo;३&rdquo; हा संदेशच राहतो. अपग्रेड केल्यानंतर बंद; नवीन इन्स्टॉलसाठी चालू.',
            'analytics_heading' => '<strong>विश्लेषण पान</strong>',
            'analytics_body' => '<code>tickets/csat/</code> येथील विश्लेषण डॅशबोर्ड उघडण्यासाठी ⭐ <strong>CSAT</strong> नेव्ह बटणावर (रोटा आणि सेटिंग्ज यांच्यामध्ये) क्लिक करा. कालावधी निवडता येतो: ७ / ३० / ९० / ३६५ दिवस.',
            'card_kpi_title' => 'KPI टाइल्स',
            'card_kpi_body' => 'सरासरी रेटिंग (५ पैकी), प्रतिसाद संख्या, प्रतिसाद दर (प्रतिसाद ÷ पाठवलेले)',
            'card_dist_title' => 'गुण वितरण',
            'card_dist_body' => '१–५ रेटिंगचा बार चार्ट, अचूक संख्या आणि टक्केवारीसह',
            'card_leader_title' => 'प्रत्येक विश्लेषकाचा लीडरबोर्ड',
            'card_leader_body' => 'प्रत्येक विश्लेषकासाठी सरासरी रेटिंग + प्रतिसाद संख्या, सरासरीनुसार उतरत्या क्रमाने. विकास चर्चांसाठी वापरा',
            'card_recent_title' => 'अलीकडील प्रतिसाद',
            'card_recent_body' => 'रेटिंग्ज नवीनतम आधी, प्रति पान २५, मोकळ्या मजकुरातील टिप्पण्या आणि त्या देणाऱ्या ग्राहकासह, मूळ तिकिटाशी जोडलेले',
            'analytics_filters' => 'शीर्षकाखालील फिल्टरने पान मर्यादित करा: <strong>पासून / पर्यंत</strong> तारीख श्रेणी (दिवस बटणांऐवजी), <strong>रेटिंग</strong> गट (सकारात्मक ४-५, तटस्थ ३, नकारात्मक १-२), एक <strong>विश्लेषक</strong> आणि एक <strong>ग्राहक</strong>. विश्लेषक आणि ग्राहक पानावरील प्रत्येक आकडा मर्यादित करतात; रेटिंग गट फक्त प्रतिसादांची यादी मर्यादित करतो, त्यामुळे सरासरीला अर्थ राहतो. फोनवर फिल्टर स्क्रीनच्या तळाशी असलेल्या <strong>फिल्टर</strong> बटणामागे असतात. फिल्टर केलेले पान बुकमार्क करता येते.',
            'analytics_company' => 'प्रत्येक आकडा हेडरमधील <strong>कंपनी स्विचर</strong> नुसार बदलतो: तुम्ही निवडलेली कंपनी, किंवा <strong>सर्व कंपन्या</strong> अंतर्गत तुम्हाला दिसणाऱ्या सर्व कंपन्या.',
            'analytics_tip' => 'प्रत्येक विश्लेषकाचे श्रेय तिकीट पुन्हा नेमल्यानंतरही टिकते, कारण विश्लेषक id पाठवतानाच सर्वेक्षण ओळीत नोंदवला जातो, थेट शोधला जात नाही. बंद होण्यापूर्वी तिकीट अनेकांकडे गेले तरी ते प्रत्यक्षात ज्याने बंद केले त्या विश्लेषकाकडे रेटिंग जाते.',
            'one_heading' => '<strong>प्रति तिकीट एक सर्वेक्षण</strong>',
            'one_body' => '<em>प्रति तिकीट एक सर्वेक्षण</em> चालू असल्यास (डीफॉल्ट), पुन्हा उघडून पुन्हा बंद केलेल्या तिकिटाला विश्लेषकाने मॅन्युअली सुरू केल्यासच आणखी एक सर्वेक्षण मिळते &mdash; वारंवार फिरणाऱ्या तिकिटावर सर्वेक्षणांचा मारा थांबतो. प्रत्येक बंद करण्यावर नवीन सर्वेक्षण हवे असल्यास ते बंद करा.',
        ],
        'users' => [
            'heading' => 'वापरकर्ता व्यवस्थापन',
            'intro' => '<strong>वापरकर्ते</strong> नेव्ह बटण <code>tickets/users.php</code> उघडते &mdash; प्रत्येक एंड युजरची (तिकिटे नोंदवणारे लोक, विश्लेषक नव्हे) डिरेक्टरी, प्रत्येकाच्या तिकीट इतिहासासह.',
            'p_intro' => 'वापरकर्ते सिस्टममध्ये चार प्रतिक्रियात्मक मार्गांनी येतात &mdash; पोर्टलवरील स्वयं-नोंदणी, नवीन प्रेषकाकडून आलेला इनबाउंड ईमेल, मेलबॉक्स पोलर, किंवा ट्रिगर झालेल्या तिकिटातून वर्कफ्लो इंजिनने तयार केलेला वापरकर्ता. बहुतेक प्रकरणे यातच येतात, पण वापरकर्ते पृष्ठावर तुम्ही वापरकर्ता <strong>आधीच तयार</strong> करू शकता (उदा. लवकरच प्रवेश लागणारा नवीन सहकारी) आणि विद्यमान ओळी <strong>संपादित</strong> किंवा <strong>हटवू</strong> शकता.',
            'add_heading' => '<strong>वापरकर्ता जोडा</strong>',
            'add_body' => 'वापरकर्त्यांच्या यादीच्या शीर्षकातील <strong>जोडा</strong> बटण व्यक्ती संपादक उघडते. <strong>मालमत्ता &rarr; वापरकर्ते</strong> मध्ये उघडणारा हाच संपादक आहे, त्यामुळे तुम्ही कोणत्याही स्क्रीनवर असलात तरी व्यक्ती सारख्याच पद्धतीने जोडली आणि बदलली जाते:',
            'add_email' => '<strong>ईमेल</strong> &mdash; पर्यायी, कारण डिरेक्टरीमधून साइन इन करणाऱ्या लोकांचा मेलबॉक्स नसू शकतो; त्यांना त्याऐवजी साइन-इन नावाने शोधले जाते. ईमेल पत्ता किंवा डिस्प्ले नाव यापैकी एक द्या. पत्ता अद्वितीय असला पाहिजे आणि तो एखाद्या विश्लेषकाचा नसावा.',
            'add_names' => '<strong>डिस्प्ले नाव / पसंतीचे नाव</strong> &mdash; पर्यायी. पसंतीचे नाव म्हणजे ईमेलमध्ये वापरकर्त्याला ज्या नावाने अभिवादन केले जाते (उदा. <em>"Ed Mozley"</em> ऐवजी <em>"Ed"</em>).',
            'add_password' => '<strong>पासवर्ड</strong> &mdash; पर्यायी. रिकामा सोडल्यास <em>पासवर्डशिवाय</em> खाते तयार होते &mdash; इनबाउंड तिकिटांचे वापरकर्ते ज्या स्थितीत सुरू होतात अगदी तीच स्थिती. वापरकर्ता नंतर सेल्फ-सर्व्हिस पोर्टलच्या नोंदणी प्रक्रियेतून स्वतःचा पासवर्ड सेट करून खाते ताब्यात घेऊ शकतो.',
            'add_details' => '<strong>पदनाम, विभाग, कार्यालय, फोन, मोबाइल, कर्मचारी ID आणि मॅनेजर</strong> &mdash; सर्व पर्यायी, आणि सर्व लॉगिनबद्दल नव्हे तर <em>व्यक्ती</em>बद्दल. भरण्यासारखे: <strong>कार्यालय</strong> सांगते की कोणी कोणत्या साइटवर आहे, <strong>मॅनेजर</strong> रिपोर्टिंग लाइन नोंदवतो (शोधण्यासाठी नावाचा काही भाग टाइप करा), आणि <strong>कर्मचारी ID</strong> हा पेरोल सिस्टमशी जुळवणी करताना जोडणारी की असते, कारण त्या सिस्टमला ईमेल पत्ता माहीतच नसतो. डिरेक्टरीमधून आयात केल्यास हे सर्व भरलेले येते. CardDAV अ‍ॅड्रेस बुक कर्मचारी ID आणि मॅनेजर वगळता सर्व काही भरते, कारण संपर्क कार्डमध्ये ते साठवायला जागा नसते.',
            'managed_heading' => '<strong>इतरत्र सांभाळल्या जाणाऱ्या व्यक्ती</strong>',
            'source_body' => '<strong>व्यक्ती कुठून आली</strong> हे त्यांच्या तपशीलात दिलेले असते (<em>Details from: Contoso AD - directory</em>), आणि शोध बॉक्सखालील <strong>स्रोत</strong> फिल्टर फक्त एका डिरेक्टरी किंवा अ‍ॅड्रेस बुकमधील लोक, किंवा फक्त FreeITSM मध्ये जोडलेले लोक दाखवतो, प्रत्येकासमोर संख्येसह. कोणीतरी स्रोताशी जोडलेले असल्यावरच तो दिसतो.',
            'add_book_body' => '<strong>अ‍ॅड्रेस बुकमध्ये जोडा.</strong> ईमेल करणारी एखादी व्यक्ती येथे असते पण कोणत्याही अ‍ॅड्रेस बुकमध्ये नसते. प्रशासकाने <em>विश्लेषकांना या अ‍ॅड्रेस बुकमध्ये लोक जोडू द्या</em> (सिस्टम &rarr; प्रमाणीकरण, अ‍ॅड्रेस बुकवर) चालू केले असल्यास, त्या व्यक्तीला संपादित करा बटणाशेजारी <strong>अ‍ॅड्रेस बुकमध्ये जोडा</strong> बटण मिळते. ते आधी विचारते, कार्डवर काय जाईल ते दाखवते, मग त्यांचा संपर्क तयार करून जोडते &mdash; तीच व्यक्ती, प्रत नव्हे. अ‍ॅड्रेस बुकमध्ये आधीच ईमेल पत्ता असलेल्या व्यक्तीला ते जोडणार नाही (त्याऐवजी आयात चालवा), आणि पुढील आयात नवीन संपर्क उचलेल याची खात्री करते, नाहीतर कार्ड परत काढून घेते.',
            'managed_body' => 'व्यक्ती LDAP किंवा Active Directory मधून, किंवा CardDAV अ‍ॅड्रेस बुकमधून आयात केली असल्यास, त्या स्रोताच्या मालकीचे तपशील <strong>केवळ-वाचनीय</strong> असतात आणि मोडल ते धूसर करते. ते जिथून आले तोच खरा स्रोत आहे, आणि पुढील आयात येथे टाइप केलेले काहीही अधिलिखित करेल, म्हणून जतन तासाभराने शांतपणे परत बदलण्याऐवजी थेट नाकारले जाते. <strong>कोणते</strong> तपशील हे स्रोतावर अवलंबून आहे: डिरेक्टरी सातही तपशीलांची मालक असते, तर अ‍ॅड्रेस बुक पाचची &mdash; त्यात कर्मचारी क्रमांक किंवा रिपोर्टिंग लाइन ठेवायला जागा नसते, त्यामुळे ते दोन तुमच्याकडेच भरायला राहतात. आणि अ‍ॅड्रेस बुकवर <em>बदल परत लिहा</em> चालू असल्यास, त्यापैकी कोणतेही लॉक नसते: तुम्ही टाइप केलेले संपर्क कार्डवर पाठवले जाते, त्यामुळे पुढील आयातीला परत बदलण्यासारखे काही उरत नाही. रेकॉर्डवरील बाकी सर्व, त्यांची कंपनी आणि पासवर्डसह, नेहमी संपादित करता येते.',
            'edit_heading' => '<strong>वापरकर्ता संपादित करा</strong>',
            'edit_body' => 'यादीतून वापरकर्ता निवडा, मग तपशील शीर्षकातील <strong>संपादित करा</strong> क्लिक करा. तोच संपादक, आधीच भरलेला. पासवर्डशिवाय जतन केल्यास विद्यमान हॅश तसाच राहतो; पासवर्ड दिल्यास तो रीसेट होतो. त्यांचा मॅनेजर तुम्हाला न दिसणाऱ्या कंपनीतील कोणी असल्यास, मॅनेजर बॉक्स तसे सांगतो आणि तुम्ही दुसरे कोणी निवडले नाही तर मॅनेजर आहे तसाच राहतो.',
            'signin_body' => '<strong>यासह साइन इन करतो</strong> हे दाखवते की व्यक्ती कोणत्या सिंगल साइन-ऑन प्रदात्याशी जोडलेली आहे. त्याशेजारील <strong>लिंक काढा</strong>, पुष्टीनंतर, ती लिंक काढते जेणेकरून त्यांचे पुढील साइन-इन नव्याने सुरू होते &mdash; दुसऱ्या प्रदात्याकडे गेलेल्या किंवा चुकीच्या खात्याशी जोडल्या गेलेल्या व्यक्तीसाठी. डिरेक्टरी सिंकने सांभाळल्या जाणाऱ्या लोकांसाठी ते दिले जात नाही, कारण सिंक त्यांना पुन्हा जोडेलच.',
            'company_body' => 'तुमच्याकडे एकापेक्षा जास्त असल्यावर <strong>कंपनी</strong> दिसते. नवीन व्यक्तीसाठी, रिकामे सोडल्यास कंपनी त्यांच्या ईमेल पत्त्यावरून ठरवली जाते; विद्यमान व्यक्तीसाठी, रिकामे म्हणजे कंपनी नाही, आणि त्यांची तिकिटे ट्रायेजमध्ये जातात.',
            'managers_heading' => '<strong>मॅनेजर</strong>',
            'managers_body' => 'सेल्फ-सर्व्हिस पोर्टलमध्ये व्यक्तीला <strong>मॅनेजर</strong> बनवता येते: त्यांना <strong>टीम तिकिटे</strong> टॅब मिळतो ज्यात ते सांभाळत असलेल्या लोकांची तिकिटे दिसतात. प्रशासकाने <strong>सिस्टम &rarr; मॅनेजर</strong> अंतर्गत चालू करेपर्यंत ते बंद असते; तिथेच मॅनेजर त्या तिकिटांना उत्तर देऊ शकतात की बंद करू शकतात, आणि गोपनीय तिकिटाचे त्यांना काय दिसते (डीफॉल्टनुसार काहीही नाही) हेही ठरते.',
            'managers_sources' => 'कोणीतरी दोन प्रकारे मॅनेजर असते, दोन्ही एकाच वेळी: ते इतरांच्या रेकॉर्डवर <strong>मॅनेजर</strong> असतात (हाताने, किंवा तुमच्या डिरेक्टरीतून), आणि त्यांच्यासाठी <strong>व्यवस्थापन ओळी</strong> सेट केलेल्या असतात. त्या व्यक्तीसाठी पूर्ण-स्क्रीन पृष्ठ उघडण्यासाठी संपादित करा शेजारील <strong>मॅनेजर प्रवेश</strong> क्लिक करा; तिथे तुम्ही त्यांना सर्वजण, विशिष्ट लोक, लोकांचे गट, विभाग किंवा त्यांची संपूर्ण रिपोर्टिंग लाइन देऊ शकता, आणि लोकांना <strong>वगळू</strong> शकता &mdash; वगळणे नेहमी जिंकते, मॅनेजर फील्डवरही. मॅनेजर्स आधीच चालू असल्यासारखे गणन करून पृष्ठ ते किती लोकांना पाहू शकतात ते दाखवते आणि त्यांची यादी करते, म्हणजे चालू करण्यापूर्वी तुम्ही तपासू शकता. त्या यादीतील कोणावरही क्लिक करून मॅनेजर त्यांना <strong>का</strong> पाहू शकतो आणि ते कसे थांबवायचे ते पहा.',
            'managers_rules' => 'मॅनेजर फक्त स्वतःच्या कंपनीतील लोकांना पाहतो, स्वतःला कधीही नाही, आणि सोडून गेल्यानंतर काहीच नाही. विभाग प्रत्येक व्यक्तीवर टाइप केलेल्या नावाशी जुळवले जातात, त्यामुळे नाव बदललेला विभाग जुळणे थांबवतो &mdash; कोणाशीही न जुळणाऱ्या विभाग ओळीबद्दल पृष्ठ आणि सिस्टम &rarr; मॅनेजर इशारा देतात. डीफॉल्टनुसार फक्त प्रशासक व्यवस्थापन ओळी बदलू शकतात; सिस्टम &rarr; मॅनेजर मध्ये लोक संपादित करू शकणाऱ्या कोणालाही ते खुले करता येते.',
            'delete_heading' => '<strong>वापरकर्ता हटवा</strong>',
            'delete_body' => '<strong>हटवा</strong> बटण <strong>FK-सुरक्षित</strong> आहे: वापरकर्ता कोणत्याही तिकिटांवर विनंती करणारा असल्यास किंवा <code>users_assets</code> मध्ये कोणत्याही ओळी असल्यास ते नकार देते, आणि स्पष्ट <em>"Cannot delete: this user is the requester on N ticket(s). Reassign or close those tickets first."</em> संदेश परत करते. ऑडिट इतिहास कधीही शांतपणे तुटू शकत नाही.',
            'tip' => 'सर्व मोडल फील्डमध्ये ब्राउझर ऑटोफिल बंद आहे (पासवर्ड फील्डवरील <code>autocomplete="new-password"</code> सह), जेणेकरून ज्या फॉर्मचा संपूर्ण उद्देशच <em>दुसऱ्या कोणाचा</em> रेकॉर्ड तयार करणे आहे त्यात विश्लेषकाची स्वतःची जतन केलेली क्रेडेन्शियल्स सुचवली जात नाहीत.',
            'groups_heading' => '<strong>गट</strong>',
            'groups_body' => '<strong>लोक</strong> शेजारील <strong>गट</strong> टॅबमध्ये लोकांचे नावाचे गट असतात &mdash; विश्लेषक आणि सेल्फ-सर्व्हिस पोर्टल वापरकर्ते एकाच गटात एकत्र. गट येथे एकदा तयार केला जातो आणि मग FreeITSM मध्ये सर्वत्र वापरला जातो, त्यामुळे ज्ञान फोल्डरचा प्रवेश किंवा प्रशिक्षण अभ्यासक्रम देण्यासाठी तुम्हाला तीच यादी दोनदा बनवावी लागत नाही.',
            'groups_make' => 'गट टॅबवर <strong>जोडा</strong> ने <strong>एक तयार करा</strong>: एक नाव, आणि भरण्यासारखे वर्णन, कारण पुढच्या व्यक्तीला गट कशासाठी आहे ते कळले पाहिजे.',
            'groups_add' => 'लोकांना शोधून <strong>जोडा</strong> &mdash; ते विश्लेषक आणि पोर्टल वापरकर्ते एकत्र शोधते, त्यामुळे कोणी कोणत्या प्रकारचे आहे हे तुम्हाला माहीत असण्याची गरज नाही.',
            'groups_expiry' => 'प्रवेश तात्पुरता असेल तेथे <strong>सदस्यत्वाला समाप्ती तारीख द्या</strong>. दोन आठवड्यांसाठी साइटवर असलेले तीन इंजिनिअर शेवटच्या दिवसासह जोडले जातात आणि ती तारीख गेल्यावर आपोआप गटातून बाहेर पडतात. कालबाह्य सदस्यत्व यादीत राहते, कालबाह्य म्हणून चिन्हांकित, त्यामुळे कोणाला प्रवेश होता आणि कधीपर्यंत हे तुम्ही अजूनही पाहू शकता.',
            'groups_uses' => '<strong>गट कशासाठी उपयुक्त आहे:</strong> ज्ञान फोल्डरचा प्रवेश देणे, आणि लोकांच्या संचाला एकाच वेळी LMS प्रशिक्षण नेमणे. सदस्यत्वातील बदल लगेच लागू होतात &mdash; नंतर पुन्हा लागू करण्यासारखे काही नाही.',
            'groups_admin' => '<strong>तिकिटे मॉड्यूल असलेला कोणीही गट पाहू शकतो; फक्त प्रशासक त्यात बदल करू शकतो.</strong> एखाद्याला गटात जोडल्याने त्यांना प्रतिबंधित ज्ञान फोल्डरचा प्रवेशही मिळू शकतो, म्हणजे हे प्रवेश देणे आहे, फाइलिंगचे काम नव्हे.',
        ],
        'dash' => [
            'heading' => 'डॅशबोर्ड',
            'intro' => 'तिकीट डॅशबोर्ड सानुकूल करण्यायोग्य Chart.js विजेट्ससह एका नजरेत विश्लेषण देतो. प्रत्येक विश्लेषकाची स्वतःची डॅशबोर्ड मांडणी असते, त्यामुळे तुमच्या भूमिकेसाठी महत्त्वाच्या मेट्रिक्सवर तुम्ही लक्ष केंद्रित करू शकता &mdash; वैयक्तिक कामाचा भार असो, संघाची क्षमता असो किंवा SLA अनुपालन.',
            'step1' => '<strong>लायब्ररी उघडा</strong> &mdash; संपादन मोडमध्ये जाण्यासाठी डॅशबोर्ड संपादित करा क्लिक करा, मग विजेट लायब्ररी ब्राउझ करा. तयार विजेट्समधून निवडा किंवा चार्ट प्रकार आणि एकत्रित करायची डेटा प्रॉपर्टी निवडून स्वतःचे बनवा.',
            'step2' => '<strong>विजेट्स जोडा</strong> &mdash; लायब्ररीतील कोणत्याही विजेटवरील + बटण क्लिक करून ते तुमच्या डॅशबोर्डवर जोडा. ते लगेच दिसते आणि तुमच्या तिकीट डेटाबेसमधील लाइव्ह डेटा दाखवू लागते.',
            'step3' => '<strong>कॉन्फिगर करा</strong> &mdash; कोणत्याही विजेटवरील कॉग आयकॉन क्लिक करून त्याचे शीर्षक, चार्ट प्रकार (बार, पाय, डोनट, लाइन, स्टॅक्ड बार, मल्टी-लाइन), तारीख श्रेणी फिल्टर, विभाग फिल्टर आणि वेळ गटीकरण (दैनिक, साप्ताहिक, मासिक) सानुकूल करा.',
            'step4' => '<strong>मांडा</strong> &mdash; विजेट्स ड्रॅग आणि ड्रॉप करून त्यांचा क्रम बदला. तुमची मांडणी प्रत्येक विश्लेषकासाठी जतन केली जाते, त्यामुळे ती सत्रांमध्ये टिकून राहते.',
            'examples' => 'सामान्य विजेट उदाहरणे: <strong>स्थितीनुसार तिकिटे</strong> (खुली विरुद्ध निराकरण झालेली विरुद्ध बंद दाखवणारा डोनट चार्ट), <strong>प्राधान्यानुसार तिकिटे</strong> (तीव्रतेनुसार संख्येचा बार चार्ट), <strong>साप्ताहिक संख्या</strong> (कालांतराने नवीन तिकिटांचा मागोवा घेणारा लाइन चार्ट), आणि <strong>विश्लेषकाचा कामाचा भार</strong> (प्रत्येक विश्लेषकाची सक्रिय तिकिटे दाखवणारा स्टॅक्ड बार).',
            'tip' => 'सध्याच्या कामगिरीची मागील कालावधींशी तुलना करण्यासाठी वैयक्तिक विजेट्सवर तारीख श्रेणी फिल्टर वापरा. उदाहरणार्थ, "या महिन्याचा विरुद्ध मागील महिना" दृश्य तिकीट संख्येतील ट्रेंड लवकर ओळखण्यास मदत करते.',
        ],
        'cal_rota' => [
            'heading' => 'दिनदर्शिका &amp; रोटा',
            'intro' => 'दोन वेळापत्रक साधने तुमच्या संघाला व्यवस्थित ठेवतात: कालांतराने कामाचा भार दाखवणारी तिकीट दिनदर्शिका, आणि शिफ्ट आणि ऑन-कॉल उपलब्धता सांभाळण्यासाठी कर्मचारी रोटा.',
            'cal_heading' => '<strong>दिनदर्शिका दृश्य</strong>',
            'cal_body' => 'दिनदर्शिका तुम्ही नियोजित केलेले प्रत्येक तिकीट &mdash; तिकिटावरच आणि इनबॉक्सच्या राइट-क्लिक मेनूवर असलेल्या <strong>काम शेड्यूल करा</strong> द्वारे &mdash; ठरलेल्या वेळी रंगीत ब्लॉक म्हणून दाखवते, निश्चित तासाऐवजी त्याच्या <strong>प्रत्यक्ष लांबीने</strong> काढलेले. लाल ब्लॉक <em>जास्त</em> प्राधान्याचे, हिरवे <em>कमी</em>, आणि निळा बाकी सर्व. नेव्हिगेट करण्यासाठी <em>आज</em>, <em>&lt;</em> / <em>&gt;</em> शेवरॉन, आणि <strong>महिना / आठवडा / दिवस</strong> टॉगल वापरा.',
            'cal_scope' => '<strong>माझे किंवा सर्वजण.</strong> दिनदर्शिका तुमच्या स्वतःच्या नियोजित कामावर उघडते, दृश्य बटणांशेजारी <strong>सर्वजण</strong> स्विचसह; तुमची निवड लक्षात ठेवली जाते. सर्वजण मध्ये प्रत्येक तिकिटावर <strong>ते कोणाचे आहे त्याचा रंग</strong> असतो, स्क्रीनवर प्रत्यक्ष असलेल्या लोकांची नावे सांगणाऱ्या लेजंडसह, आणि तिकिटावर फिरवल्यास नजर न हलवता ते कोणाचे आहे ते कळते. कोणापासूनही काही लपवलेले नाही &mdash; ही तीच तिकिटे आहेत जी इनबॉक्स आधीच दाखवतो.',
            'cal_edit' => '<strong>काम पुन्हा मांडणे.</strong> तिकीट वेगळ्या दिवशी किंवा वेळी <strong>ड्रॅग करा</strong>: महिना दृश्यात ते आपली वेळ ठेवते, आणि आठवडा व दिवस दृश्यात तुम्ही जिथे सोडाल ती वेळ घेते, जवळच्या पंधरा मिनिटांवर बसवलेली. त्याची लांबी कधीच बदलत नाही &mdash; ड्रॅग करणे म्हणजे <em>तेव्हा सुरू करा</em>, <em>जास्त वेळ करा</em> नव्हे. किंवा तिकीट उघडण्यासाठी त्यावर <strong>क्लिक करा</strong>, जिथे तुम्ही तारीख, वेळ, कालावधी आणि दिवसभर सेटिंग बदलू शकता, किंवा वेळापत्रक पूर्णपणे साफ करू शकता. दिनदर्शिका <strong>दर काही सेकंदांनी स्वतः रिफ्रेश होते</strong>, त्यामुळे सहकाऱ्याने काही नियोजित केले तर तुम्ही रीलोड न करता ते दिसते &mdash; आणि तुम्ही तिकीट उघडलेले असताना किंवा ड्रॅग करत असताना ती थांबते.',
            'cal_month' => '<strong>महिना दृश्य</strong> &mdash; आठवड्याच्या दिवसांच्या शीर्षक पट्टीसह क्लासिक 6-ओळींचा ग्रिड; प्रत्येक दिवसाच्या सेलमध्ये सुरुवातीच्या वेळेसह जास्तीत जास्त तीन तिकीट पिल्स दिसतात, तसेच <em>+N अधिक</em> दुवा जो तुम्हाला त्या तारखेच्या दिवस दृश्यात नेतो. आजचा दिवस हायलाइट केलेला असतो.',
            'cal_week' => '<strong>आठवडा दृश्य</strong> &mdash; 24-तासांच्या उभ्या टाइमलाइनवर वर सोम&ndash;रवि. तिकिटे त्यांच्या नियोजित लांबीने दाखवली जातात, त्यामुळे 15 मिनिटांचे काम आणि दुपारभराचे रीबिल्ड वेगळे दिसतात. दिवसभराचे तिकीट संपूर्ण स्तंभ व्यापण्याऐवजी त्या दिवसाच्या वर बारीक पट्टी म्हणून बसते. आजचा स्तंभ हायलाइट केलेला असतो; तासांचा ग्रिड स्क्रोल होत असताना आठवड्याच्या दिवसांचे शीर्षक जागेवरच राहते.',
            'cal_day' => '<strong>दिवस दृश्य</strong> &mdash; निवडलेल्या दिवसासाठी एकच उंच स्तंभ, तीच 24-तासांची टाइमलाइन. तिकिटे <code>ticket_number &mdash; subject</code> आणि सुरुवातीची वेळ दाखवणाऱ्या मोठ्या ब्लॉक्स म्हणून दिसतात; तपशील उघडण्यासाठी किंवा ते केव्हा होते ते बदलण्यासाठी एकावर क्लिक करा.',
            'rota_heading' => '<strong>कर्मचारी रोटा</strong>',
            'rota_body' => 'रोटा पृष्ठ टीम लीड्स आणि मॅनेजर्सना आठवडाभर विश्लेषकांच्या शिफ्ट नियोजित करू देते. मानक कामाचे तास ठरवा, ऑन-कॉल कालावधी नेमा, आणि सुट्ट्या किंवा गैरहजेरी चिन्हांकित करा जेणेकरून कोण उपलब्ध आहे हे संघाला नेहमी कळेल.',
            'rota_step1' => '<strong>रोटा ग्रिड पहा</strong> &mdash; रोटा एका अक्षावर विश्लेषक आणि दुसऱ्यावर दिवस दाखवतो, शिफ्ट ब्लॉक्स एका नजरेत कव्हरेज दाखवतात.',
            'rota_step2' => '<strong>शिफ्ट जोडा किंवा संपादित करा</strong> &mdash; शिफ्ट प्रकार नेमण्यासाठी (उदा. Early, Late, Night, On-Call) सेलवर क्लिक करा. बदल लगेच जतन होतात.',
            'rota_step3' => '<strong>आधी नियोजन करा</strong> &mdash; रोटा आधीच बनवण्यासाठी आठवड्यांनी पुढे जा. यामुळे ज्ञात व्यस्त कालावधी, सुट्ट्या किंवा प्रशिक्षण दिवसांत पुरेसे कव्हरेज राहते.',
            'rota_step4' => '<strong>एकाच वेळी अनेक सेल भरा</strong> &mdash; सेलवर <strong>राइट-क्लिक</strong> करा आणि त्यातील शिफ्ट उचलण्यासाठी <em>कॉपी</em> निवडा, मग दुसऱ्यावर राइट-क्लिक करून <em>पेस्ट</em> करा. एकापेक्षा जास्त सेलसाठी, त्यांच्या <strong>ब्लॉकवर ड्रॅग करा</strong> (किंवा एक-एक सेल ctrl-क्लिक करा) आणि सर्वांमध्ये पेस्ट करा. <strong>दिवसाच्या शीर्षकावर</strong> फिरवल्यास तो पूर्ण दिवस उजळतो, आणि <strong>विश्लेषकाच्या नावावर</strong> फिरवल्यास त्यांचा पूर्ण आठवडा उजळतो &mdash; दोन्हीपैकी एकावर राइट-क्लिक करून सर्वांमध्ये पेस्ट करा. काही सेलमध्ये आधीच शिफ्ट असल्यास मेनू साध्या शब्दांत दोन्ही मार्ग देतो &mdash; <em>सर्व 7 मध्ये पेस्ट करा</em> आणि <em>6 रिकाम्या सेलमध्ये पेस्ट करा</em> &mdash; म्हणजे तुम्ही निश्चित करण्यापूर्वी निवडता, नंतर नव्हे. अधिलिखित करताना पुष्टी विचारली जाते आणि किती शिफ्ट बदलतील ते सांगितले जाते; रिकाम्या जागा भरणे थेट होते, कारण काहीही गमावले जात नाही. याच मेनूमधून दिवस, आठवडा किंवा निवड <strong>साफ</strong> करता येते, पुन्हा किती शिफ्ट काढल्या जातील ते सांगून.',
            'rota_step5' => '<strong>एका व्यक्तीसाठी पूर्ण दिवस किंवा पूर्ण आठवडा कॉपी करा</strong> &mdash; त्या दिवसाच्या सर्व शिफ्ट उचलण्यासाठी <strong>दिवसाच्या शीर्षकावर</strong> राइट-क्लिक करून <em>कॉपी</em> निवडा, किंवा त्यांचा पूर्ण आठवडा उचलण्यासाठी <strong>विश्लेषकाच्या नावावर</strong>. दुसऱ्या दिवशी किंवा दुसऱ्या विश्लेषकावर पेस्ट केल्याने ते जुळते: कॉपीमध्ये नसलेल्या शिफ्ट साफ केल्या जातात, त्यामुळे दोघांचे मिश्रण नव्हे तर तुम्ही कॉपी केलेला दिवस मिळतो. दिवस फक्त दुसऱ्या दिवशी आणि विश्लेषक फक्त दुसऱ्या विश्लेषकावर पेस्ट करता येतो &mdash; दिवस म्हणजे <em>प्रति व्यक्ती</em> एक शिफ्ट आणि आठवडा म्हणजे <em>प्रति दिवस</em> एक शिफ्ट, त्यामुळे एक दुसऱ्यावर ठेवण्याचा कोणताही योग्य मार्ग नाही. प्रयत्न केल्यास मेनू तसे सांगतो, आणि ते त्याऐवजी कुठे जाऊ शकते तेही सांगतो.',
            'rota_step6' => '<strong>पूर्ण आठवडा कॉपी करा</strong> &mdash; वर उजवीकडील <strong>आठवडा कॉपी करा</strong> आणि <strong>आठवडा पेस्ट करा</strong> तुम्ही पाहत असलेल्या आठवड्यातील सर्व शिफ्ट उचलून दुसऱ्या आठवड्यावर टाकतात, पुनरावृत्ती होणारा रोटा बनवण्याचा हा सर्वात जलद मार्ग आहे. पेस्ट केल्याने लक्ष्य आठवडा <em>बदलला</em> जातो, त्यामुळे किती नोंदी काढल्या जाणार आहेत ते पुष्टीमध्ये सांगितले जाते. ते फक्त ग्रिड प्रत्यक्ष दाखवत असलेल्या दिवसांना आणि लोकांनाच स्पर्श करते.',
            'tip' => 'प्रभावी क्षमता नियोजनासाठी दिनदर्शिका आणि रोटा एकत्र वापरा. दर सोमवारी सकाळी तिकिटांची वाढ दिसत असल्यास, त्या वेळेसाठी रोटामध्ये जास्त कव्हरेज नियोजित असल्याची खात्री करा.',
        ],
        'settings' => [
            'heading' => 'सेटिंग्ज',
            'intro' => 'सेटिंग्ज पृष्ठावर तुम्ही तुमच्या तिकीट प्रणालीचे मूलभूत घटक कॉन्फिगर करता. सर्व लुकअप मूल्ये, SLA लक्ष्ये, ईमेल एकत्रीकरण आणि कस्टम फील्ड येथेच व्यवस्थापित केली जातात.',
            'sla_callout_title' => 'SLA व्यवस्थापन &mdash; संपूर्ण मार्गदर्शक',
            'sla_callout_body' => 'कॉन्फिगर करता येणारे पर्याय, व्यावसायिक दिनदर्शिका, पॉझ स्थिती, उल्लंघन सूचना, cron जॉब सेटअप, तसेच एकाच टाइमझोनमधील आणि अनेक टाइमझोनमधील संघांसाठी उदाहरणे. स्वतःच्या पृष्ठाला पात्र ठरेल इतके सविस्तर.',
            'card_dept_title' => 'विभाग',
            'card_dept_body' => 'IT, HR आणि Finance सारखे विभाग तयार करा. प्रत्येक विभाग इनबॉक्समध्ये एक फोल्डर आणि डॅशबोर्डवर एक फिल्टर बनतो',
            'card_types_title' => 'तिकीट प्रकार',
            'card_types_body' => 'तुमचा डेस्क हाताळत असलेल्या विनंत्यांचे प्रकार ठरवा: Incident, Service Request, Problem, Change. प्रकारांमुळे विश्लेषकांना कामाचे वर्गीकरण करता येते',
            'card_priorities_title' => 'प्राधान्ये',
            'card_priorities_body' => 'नावे, रंग आणि क्रमासह प्राधान्य स्तर सेट करा. प्रत्येक प्राधान्य प्रतिसाद आणि निराकरणासाठीच्या SLA लक्ष्याशी जोडलेले असते',
            'card_statuses_title' => 'स्थिती',
            'card_statuses_body' => 'तिकिटाच्या जीवनचक्रातील टप्पे आपल्या गरजेनुसार बदला. डीफॉल्ट स्थितींमध्ये नवीन, खुले, प्रगतीत, प्रलंबित, निराकरण झाले आणि बंद यांचा समावेश आहे',
            'card_categories_title' => 'श्रेण्या',
            'card_categories_body' => 'तांत्रिक क्षेत्रानुसार तिकिटांचे गट करा: हार्डवेअर, सॉफ्टवेअर, नेटवर्क, प्रवेश. श्रेण्यांमुळे अहवालातील विभाजन शक्य होते',
            'card_sla_title' => 'SLA लक्ष्ये',
            'card_sla_body' => 'प्रत्येक प्राधान्यासाठी प्रतिसाद आणि निराकरण वेळेची लक्ष्ये ठरवा. SLA टायमर तिकिटांवर दिसतात आणि उल्लंघनाच्या इशाऱ्यांना चालना देतात',
            'card_email_title' => 'ईमेल आयात',
            'card_email_body' => 'ईमेल आपोआप नवीन तिकिटे म्हणून आयात करण्यासाठी मेलबॉक्स (Exchange, Microsoft 365) जोडा. उत्तरे विद्यमान तिकिटांमध्येच थ्रेड होतात',
            'card_custom_title' => 'कस्टम फील्ड',
            'card_custom_body' => 'डीफॉल्ट फील्ड संचामध्ये नसलेला, पण तुमच्या संस्थेला नोंदवावा लागणारा डेटा ठेवण्यासाठी तिकिटांवर स्वतःची फील्ड जोडा',
            'card_templates_title' => 'ईमेल टेम्पलेट',
            'card_templates_body' => 'तिकिटे तयार, अद्यतनित किंवा निराकरण झाल्यावर, तसेच CSAT सर्वेक्षणासाठी अंतिम वापरकर्त्यांना पाठवली जाणारी सूचना टेम्पलेट कॉन्फिगर करा. [requester_name] आणि [csat_link] सारखे मर्ज कोड त्यात वापरा',
            'card_checklists_title' => 'चेकलिस्ट',
            'card_checklists_body' => 'ज्या तिकिटावर अनिवार्य चेकलिस्ट पायऱ्या अजून बाकी आहेत ते कोणी बंद केले, तर काय व्हावे ते ठरवा: <strong>इशारा</strong> द्या आणि बाकी पायऱ्या व तिकीट कोणी बंद केले हे नमूद करणारी अंतर्गत नोंद ठेवा, किंवा त्या पूर्ण होईपर्यंत बंद करणे <strong>रोखा</strong>. तिकीट जिथे जिथे बंद करता येते तिथे हे लागू होते - बल्क क्रिया, REST API आणि वर्कफ्लो ऑटोमेशनसह',
            'card_custom_fields_title' => 'कस्टम फील्ड',
            'card_custom_fields_body' => 'एखाद्या प्रकारच्या तिकिटाला लागणारे अतिरिक्त तपशील तयार करा - मजकूर, संख्या, तारीख, होय / नाही, तुमच्याच पर्यायांचा ड्रॉपडाउन, वेब किंवा ईमेल पत्ता - आणि प्रत्येक फील्ड काही तिकीट प्रकारांशी किंवा सर्वांशी जोडा. प्रत्येक फील्ड ठरवते की ते <strong>तिकीट नोंदवताना</strong> (नवीन तिकीट फॉर्म, REST API आणि विनंती केल्यास पोर्टल), <strong>बंद करण्यापूर्वी</strong> (अनिवार्य फील्ड नियमानुसार), किंवा दोन्ही वेळी भरणे आवश्यक आहे का, आणि पोर्टलवर <strong>विनंती करणाऱ्याला</strong> ते विचारले जावे का - जिथे विचारले जाणारे बदलले की तिकीट प्रकार निवडक दिसतो. उत्तरे तिकिटाच्या प्रॉपर्टीज पॅनेलमध्ये आणि त्याच्या इतिहासात दिसतात. तिकिटाचा प्रकार बदलल्यास नवीन प्रकाराला नसलेली उत्तरे लपवली जातात, पण कधीही हटवली जात नाहीत',
            'card_mandatory_title' => 'अनिवार्य फील्ड',
            'card_mandatory_body' => 'तिकीट बंद होण्यापूर्वी जी फील्ड भरलेली असणे आवश्यक आहे ती टिक करा - श्रेणी, निराकरण कोड, मालक वगैरे. मग एखादे फील्ड रिकामे असताना कोणी तिकीट बंद केले तर काय व्हावे ते निवडा: <strong>इशारा</strong>, सर्व्हिस डिलिव्हरी मॅनेजरसारख्या कोणालातरी <strong>इशारा आणि ईमेल</strong>, किंवा बंद करणे <strong>नाकारा</strong>. वेगळ्या स्विचमुळे हे तिकिटावर अंतर्गत नोंद म्हणून नोंदवले जाते. कंपनीसाठी बंद केलेले फील्ड कधीही आवश्यक नसते आणि तिकिटे मर्ज केल्याने हे कधीही सक्रिय होत नाही. तिकीट जिथे जिथे बंद करता येते तिथे हे लागू होते - बल्क क्रिया, REST API आणि वर्कफ्लो ऑटोमेशनसह',
            'card_cleanup_title' => 'Reply Cleanup AI',
            'card_cleanup_body' => 'उत्तर संपादकातील ✨ Cleanup बटणासाठी Anthropic key + मॉडेल + स्वर. बिलिंग स्वतंत्र दिसावे म्हणून इतर AI वैशिष्ट्यांपेक्षा वेगळी key',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'पाठवण्याचा मोड (बंद / स्वयंचलित / मॅन्युअल), विलंब, प्रति तिकीट एकच संरक्षण, मापन (तारे किंवा इमोजी). संपूर्ण प्रवाहासाठी विभाग ६ पहा',
            'email_heading' => '<strong>ईमेल आयात तपशीलवार</strong>',
            'email_body' => 'ईमेल आयात वैशिष्ट्य तुमच्या शेअर्ड मेलबॉक्सशी जोडले जाते आणि नवीन संदेश तिकिटे म्हणून आणते. अंतिम वापरकर्त्याने तुमच्या सपोर्ट पत्त्यावर (उदा. support@yourcompany.com) ईमेल पाठवला की FreeITSM ईमेलचा विषय शीर्षक आणि ईमेलचा मजकूर वर्णन म्हणून घेऊन तिकीट तयार करते. प्रेषकाने सूचना ईमेलला उत्तर दिल्यास, डुप्लिकेट तयार न करता ते उत्तर विद्यमान तिकिटामध्ये थ्रेड होते.',
            'email_step1' => '<strong>मेलबॉक्स कॉन्फिगर करा</strong> &mdash; सेटिंग्जमध्ये जा आणि तुमचे Exchange किंवा Microsoft 365 क्रेडेन्शियल्स प्रविष्ट करा. सुरक्षित, पासवर्ड-विरहित कनेक्शनसाठी OAuth ऑथेंटिकेशन समर्थित आहे.',
            'email_step2' => '<strong>पोलिंग अंतराल सेट करा</strong> &mdash; FreeITSM नवीन संदेशांसाठी मेलबॉक्स किती वेळाने तपासेल ते निवडा. अंतराल कमी असला की तिकिटे लवकर तयार होतात.',
            'email_step3' => '<strong>डीफॉल्ट ठरवा</strong> &mdash; ईमेलमधून तयार होणाऱ्या तिकिटांसाठी डीफॉल्ट विभाग, प्रकार आणि प्राधान्य सेट करा. आयात केल्यानंतर विश्लेषक हे बदलू शकतात.',
            'tip' => 'सर्व अंतिम वापरकर्ता संवादात व्यावसायिक आणि एकसमान स्वर राखण्यासाठी ईमेल टेम्पलेट वापरा. टेम्पलेटमध्ये तिकीट संदर्भ, विनंती करणाऱ्याचे नाव, विश्लेषकाचे नाव आणि स्थितीसाठी डायनॅमिक प्लेसहोल्डर वापरता येतात.',
            'closemsg_heading' => '<strong>तिकीट बंद करताना एकदाचा संदेश</strong>',
            'closemsg_body' => '<code>[ticket_closed_message]</code> हे सक्रिय <strong>तिकीट बंद केले</strong> टेम्पलेटमध्ये कुठेही ठेवा, आणि त्यानंतर तिकिटाची स्थिती बंद अशा स्थितीवर सेट करताना विश्लेषकाला एक वाक्य विचारले जाते - <em>&ldquo;सुटे चार्जर तुमच्या डेस्कवर आहे&rdquo;</em>, <em>&ldquo;फोनवर ठरल्याप्रमाणे बंद करत आहे&rdquo;</em>. ते जे काही टाईप करतील ते तुम्ही प्लेसहोल्डर ठेवला आहे नेमक्या तिथेच येते, त्यामुळे त्याभोवतीच्या शब्दरचनेवर तुमचे नियंत्रण राहते. ही सेटिंग नाही आणि काहीही साठवले जात नाही: एक नोंद, एक तिकीट, एक ईमेल. काहीही टाईप न केल्यास ती ओळ फक्त नसते - रिकामी जागा नाही, अनावश्यक विरामचिन्हे नाहीत.',
            'closemsg_note' => '<strong>प्लेसहोल्डर टेम्पलेटमध्ये प्रत्यक्षात असेल तेव्हाच प्रॉम्प्ट दिसतो.</strong> त्याशिवाय विश्लेषकाने टाईप केलेले काहीही शांतपणे फेकून दिले गेले असते, आणि ज्यांना हे नको त्या प्रत्येक डेस्कला प्रत्येक वेळी तिकीट बंद करताना एक क्लिक वाढला असता. म्हणून तुम्ही ते कॉन्फिगर करता तेव्हा ते स्वतःच चालू होते आणि तुम्ही केले नसेल तेव्हा आडवे येत नाही.',
            'cat_heading' => '<strong>श्रेण्या, आणि त्यांच्या शेजारची दोन फील्ड</strong>',
            'cat_body' => 'तिकिटाचा <em>प्रकार</em> सांगतो की ही कोणत्या प्रकारची गोष्ट आहे; <em>श्रेणी</em> सांगते की ती कशाबद्दल आहे. यादी <strong>सेटिंग्ज &rarr; श्रेण्या</strong> येथे तयार करा, तसेच यापैकी काहीही तिकिटावर दिसावे की नाही हे ठरवणारे स्विचही तिथेच आहेत.',
            'cat_card_one_title' => 'श्रेणी',
            'cat_card_one_body' => 'तिकीट नोंदवताना निवडलेली, तिकीट कशाबद्दल कळवले गेले ती. तिकिटाला नेमकी एकच श्रेणी असते, त्यामुळे तुमच्या श्रेण्यांचा अहवाल नेहमी प्रत्यक्षात आलेल्या तिकिटांच्या संख्येइतकाच भरतो.',
            'cat_card_close_title' => 'बंद करताना श्रेणी',
            'cat_card_close_body' => 'तिकीट पूर्ण होताना पुन्हा विचारली जाणारी तीच यादी. सहसा विश्लेषक फक्त पुष्टी करतो - पहिला अंदाज चुकलेल्या तिकिटांवर तिची खरी किंमत कळते, आणि त्यातूनच तुमच्या सदतीस "प्रिंटर समस्यां"पैकी बारा प्रत्यक्षात नेटवर्कच्या होत्या हे समजते.',
            'cat_card_res_title' => 'निराकरण कोड',
            'cat_card_res_body' => 'तिकीट कशाबद्दल होते यापेक्षा ते कसे संपले - "दूरस्थपणे दुरुस्त केले", "प्रशिक्षण दिले", "दोष आढळला नाही". सुरुवातीपासून दहा योग्य कोड दिलेले आहेत आणि ते सर्व तुम्ही बदलू शकता.',
            'cat_rule_off' => '<strong>तिन्ही सुरुवातीला बंद असतात.</strong> आधी तुमची यादी तयार करा, मग हवी ती चालू करा. प्रत्येक कंपनीसाठी प्रत्येक वेगळे सेट करता येते.',
            'cat_rule_levels' => 'श्रेण्यांना तीन स्तरांपर्यंत उप-श्रेण्या असू शकतात, आणि कोणताही स्तर अनिवार्य नाही.',
            'cat_rule_type' => 'श्रेणी एका तिकीट प्रकाराशी जोडता येते, त्यामुळे "वापरकर्ता ऑनबोर्डिंग" फक्त सर्व्हिस रिक्वेस्टवर दिली जाते. हे जोडणे वरच्या स्तरावरच्या श्रेणीचे असते आणि तिच्या उप-श्रेण्या तिचे अनुसरण करतात.',
            'cat_rule_typechange' => '<strong>तिकिटाचा प्रकार बदलल्यास जुन्या प्रकाराची श्रेणी साफ होते</strong>, आणि तसे स्क्रीनवर सांगितले जाते. कोणत्याही प्रकाराशी जोडलेली नसलेली श्रेणी बदलानंतरही टिकते.',
            'cat_rule_portal' => 'सेल्फ-सर्व्हिस पोर्टलमध्ये श्रेणी देण्यासाठी <em>ग्राहक हे निवडू शकतात</em> टिक करा. विनंती करणाऱ्यांना सोप्या भाषेतील छोटी यादी दिसते, तर विश्लेषकांना संपूर्ण वृक्ष दिसतो.',
            'cat_rule_retire' => 'श्रेणी निवृत्त करण्यासाठी ती बंद करा &mdash; ती आधीच असलेल्या तिकिटांवर राहते आणि नवीन तिकिटांवर दिली जाणे थांबते. हटवण्यापेक्षा हे जवळजवळ नेहमीच चांगले, कारण काहीही ती अजून वापरत असेल तर हटवणे नाकारले जाते.',
            'cat_rule_report' => 'तिन्ही तिकीट डॅशबोर्डवर चार्ट करता येतात. दोन श्रेणी चार्ट सर्वात वरच्या स्तरापर्यंत एकत्र केले जातात, आणि काहीही सेट नसलेली तिकिटे लपवली जाण्याऐवजी <em>श्रेणी नसलेली</em> म्हणून मोजली जातात.',
            'cat_tip' => 'कुठून सुरू करायचे ते माहीत नसेल, तर श्रेण्या रिकाम्या ठेवा आणि फक्त <strong>निराकरण कोड</strong> चालू करा. तुमची कामाची पद्धत सर्वात लवकर बदलणारे हेच फील्ड आहे &mdash; तुमच्या पाचपैकी एक तिकीट "प्रशिक्षण दिले" म्हणून परत येत असेल, तर ती IT ची नाही तर दस्तऐवजीकरणाची समस्या आहे.',
        ],
        'tips' => [
            'heading' => 'झटपट टिपा',
            'search_title' => 'सर्व काही शोधा',
            'search_body' => 'शोध मोडल तिकीट संदर्भ, विषय, विनंती करणाऱ्यांची नावे आणि ईमेल पत्ते तपासतो. एखादा वापरकर्ता विद्यमान समस्येबद्दल फोन करतो तेव्हा संबंधित तिकिटे पटकन शोधण्यासाठी तो वापरा.',
            'sla_title' => 'तुमच्या SLA वर लक्ष ठेवा',
            'sla_body' => 'वाचन पॅनेलमध्ये प्रत्येक तिकिटावर SLA टायमर दिसतात. उल्लंघन जवळ येत असताना रंगीत निर्देशक पिवळे आणि लक्ष्य चुकल्यावर लाल होतात, त्यामुळे तुम्ही त्यानुसार प्राधान्य ठरवू शकता.',
            'reply_title' => 'इनबॉक्समधून उत्तर द्या',
            'reply_body' => 'अंतिम वापरकर्त्याला उत्तर देण्यासाठी तुम्हाला तुमचा ईमेल क्लायंट उघडण्याची गरज नाही. थेट संदेश पाठवण्यासाठी वाचन पॅनेलमधील उत्तर बटण वापरा. तो आपोआप तिकिटामध्ये थ्रेड होतो.',
            'trail_title' => 'क्रियाकलाप ट्रेल वापरा',
            'trail_body' => 'तिकिटावर काम करण्यापूर्वी त्याचा क्रियाकलाप ट्रेल पाहून घ्या. मागील विश्लेषकांच्या नोंदी, ईमेल आणि फील्डमधील बदल तुम्हाला संपूर्ण संदर्भ देतात, त्यामुळे वापरकर्त्याला माहिती पुन्हा सांगायला लावावी लागत नाही.',
            'dash_title' => 'व्यवस्थापकांसाठी डॅशबोर्ड',
            'dash_body' => 'SLA अनुपालन दर, सरासरी निराकरण वेळ आणि विभागानुसार तिकिटे यासाठी विजेट्ससह डॅशबोर्ड तयार करा. सतत सुधारणा घडवण्यासाठी तो संघ बैठकांमध्ये शेअर करा.',
            'rota_title' => 'रोटासह नियोजन करा',
            'rota_body' => 'रोटा किमान दोन आठवडे आधी भरा. दिनदर्शिका दृश्यासोबत वापरल्यास, प्रतिसाद वेळेसाठी समस्या बनण्यापूर्वीच कव्हरेजमधील फट ओळखण्यात मदत होते.',
            'drag_title' => 'वर्गीकरणासाठी ड्रॅग करा',
            'drag_body' => 'तिकिटे न उघडता अद्यतनित करण्यासाठी यादीतून फोल्डरवर ड्रॅग करा. विभाग + स्थिती उप-फोल्डर दोन्ही एकाच वेळी अद्यतनित करतात. स्प्रिंग-लोडेड विस्तारामुळे ड्रॅग करतानाच आतल्या स्थितींपर्यंत पोहोचता येते.',
            'dbl_title' => 'पूर्ण स्क्रीनसाठी डबल-क्लिक करा',
            'dbl_body' => 'सिंगल-क्लिकने तिकिटाचे वाचन पॅनेलमध्ये पूर्वावलोकन होते; एकाग्रतेने काम करण्यासाठी डबल-क्लिकने ते पूर्ण-स्क्रीन मोडमध्ये उघडते. परत येण्यासाठी विषयाशेजारील मोठे करा चिन्हावर क्लिक करा.',
            'rightclick_title' => 'झटपट क्रियांसाठी राइट-क्लिक करा',
            'rightclick_body' => 'कोणत्याही तिकिटावर राइट-क्लिक करून एका क्लिकमध्ये स्थिती, प्राधान्य किंवा नियुक्ती बदला, तसेच CMDB लिंक करा आणि वेळ नोंदवा, तेही तुम्ही सध्या वाचत असलेले तिकीट सोडून न जाता.',
            'ai_title' => 'AI कडून तुमचे उत्तर नीट करून घ्या',
            'ai_body' => 'एक कच्चा मसुदा (किंवा फक्त मुद्दे) टाईप करा आणि <strong>✨ Cleanup</strong> वर क्लिक करा &mdash; Claude त्याला अभिवादन, व्याकरण दुरुस्ती आणि समारोपासह योग्य ईमेलमध्ये पुन्हा लिहितो. पूर्ववत करण्याची लिंक ३० सेकंद दिसते.',
            'feedback_title' => 'अभिप्राय मागा',
            'feedback_body' => '<strong>सेटिंग्ज &rarr; CSAT</strong> अंतर्गत CSAT चालू करा, म्हणजे तिकिटे बंद होताना विनंती करणाऱ्यांचे आपोआप सर्वेक्षण होईल. प्रत्येक विश्लेषकाचे ट्रेंड <code>tickets/csat/</code> येथे आहेत &mdash; विकासाच्या चर्चांसाठी सोन्यासमान.',
            'precreate_title' => 'अंतिम वापरकर्ते आधीच तयार करा',
            'precreate_body' => '<strong>वापरकर्ते</strong> नेव्ह बटण वापरून तुम्ही वापरकर्त्याला तिकीट नोंदवण्याची गरज पडण्याआधीच जोडू शकता &mdash; पासवर्ड रिकामा ठेवा आणि ते सेल्फ-सर्व्हिस पोर्टलद्वारे खाते स्वतः घेऊ शकतात.',
        ],
        'companies' => [
            'heading' => 'कंपन्या &amp; ईमेल राउटिंग',
            'intro' => 'तुमचे इन्स्टॉलेशन एकापेक्षा जास्त कंपन्यांना सेवा देत असेल (उदाहरणार्थ अनेक क्लायंट्सना सहाय्य करणारा IT प्रदाता), तर प्रत्येक कंपनीची तिकिटे वेगळी ठेवली जातात. येणारा ईमेल योग्य कंपनी कशी शोधतो हे हा विभाग सांगतो.',
            'switcher_body' => 'हेडरमध्ये एक <strong>कंपनी स्विचर</strong> दिसतो. तो तुम्ही ज्या कंपनीत काम करत आहात ती ठरवतो &mdash; तिकीट सूची, फोल्डर आणि संख्या फक्त त्याच कंपनीचे दाखवतात आणि तुम्ही तयार केलेले कोणतेही तिकीट तिच्याकडे नोंदवले जाते. अनेक कंपन्यांमध्ये प्रवेश असलेले कर्मचारी त्यांच्यात स्विच करू शकतात; चुकीच्या संदर्भात उत्तर देऊ नये म्हणून सध्याची कंपनी नेहमी दाखवली जाते. कंपन्या स्वतः <strong>सिस्टम &rarr; कंपन्या</strong> अंतर्गत व्यवस्थापित करा.',
            'mailboxes_heading' => 'प्रत्येक मेलबॉक्स दोनपैकी एका प्रकारचा असतो &mdash; राउटिंग यावरून ठरते:',
            'card_pinned_title' => 'निश्चित मेलबॉक्स',
            'card_pinned_body' => 'एकाच कंपनीसाठी समर्पित (उदा. क्लायंटचा स्वतःचा <code>itsupport@</code>). त्यातील <strong>सर्व</strong> मेल त्या कंपनीकडे नोंदवला जातो &mdash; प्रेषकाकडे दुर्लक्ष केले जाते &mdash; आणि उत्तरे त्यातूनच परत जातात, त्यामुळे क्लायंटला सुरुवातीपासून शेवटपर्यंत त्यांचाच हेल्प डेस्क दिसतो.',
            'card_shared_title' => 'शेअर्ड इनटेक मेलबॉक्स',
            'card_shared_body' => 'अनेक कंपन्यांसाठी एकच पत्ता (उदा. प्रदात्याचा एकच <code>support@theprovider.com</code>). फक्त पत्त्यावरून कंपनी कळू शकत नाही, म्हणून तो <strong>ईमेल कोणी पाठवला</strong> यावरून ती ठरवतो. अनेक क्लायंट्स असलेल्या प्रदात्यासाठी शिफारस केलेली रचना.',
            'routing_heading' => 'शेअर्ड-इनटेक मेलबॉक्स कंपनी कशी निवडतो',
            'routing_body' => 'येणाऱ्या प्रत्येक ईमेलसाठी तो हे क्रमाने तपासतो आणि पहिला जुळणारा नियम लागू होतो:',
            'flow_reply' => 'तिकिटाला उत्तर',
            'flow_sender' => 'ओळखीचा प्रेषक',
            'flow_domain' => 'ओळखीचे डोमेन',
            'flow_triage' => 'ट्रायाज',
            'rule_reply' => '<strong>1. अस्तित्वातील तिकिटाला उत्तर</strong> &mdash; संदर्भावरून ओळखला गेलेला ईमेल त्या तिकिटात जोडला जातो आणि त्याची कंपनी तीच राहते.',
            'rule_sender' => '<strong>2. विशिष्ट प्रेषक पत्ता</strong> कंपनीशी जोडलेला (उदा. <code>jane@gmail.com</code> &rarr; Acme) &mdash; ती कंपनी. डोमेनच्या आधी तपासला जातो, त्यामुळे वैयक्तिक/वेबमेल पत्त्यांसाठीही तो चालतो.',
            'rule_domain' => '<strong>3. प्रेषकाचे डोमेन</strong> कंपनीशी जोडलेले (उदा. <code>@acme.com</code> वरील कोणीही &rarr; Acme) &mdash; ती कंपनी.',
            'rule_triage' => '<strong>4. जुळणी नाही</strong> &mdash; ईमेल हरवण्याऐवजी <strong>ट्रायाज</strong> रांगेत जातो (खाली पहा).',
            'keys_heading' => 'डोमेन &amp; विशिष्ट प्रेषक (प्रत्येक कंपनीसाठी सिस्टम &rarr; कंपन्या अंतर्गत सेट करा)',
            'keys_body' => 'शेअर्ड-इनटेक मेलबॉक्स याच की वर जुळणी करतो. प्रत्येक कंपनी तिच्या मालकीची ईमेल डोमेन आणि पर्यायाने वैयक्तिक प्रेषक पत्ते नोंदवते.',
            'card_domains_title' => 'ईमेल डोमेन',
            'card_domains_body' => 'कंपनीच्या मालकीची डोमेन (acme.com, acme.co.uk). नोंदणीकृत डोमेनवरील कोणताही प्रेषक त्या कंपनीकडे जातो. एक डोमेन फक्त एकाच कंपनीचे असते.',
            'card_senders_title' => 'विशिष्ट प्रेषक',
            'card_senders_body' => 'कंपनीशी जोडलेले वैयक्तिक पत्ते, डोमेनच्या आधी तपासले जातात. वैयक्तिक पत्त्यावरून ईमेल करणारा फ्रीलान्सर किंवा लहान क्लायंट यासाठी वापरा.',
            'card_public_title' => 'सार्वजनिक प्रदाते',
            'card_public_body' => 'Gmail, Outlook, Yahoo आणि तत्सम डोमेन म्हणून जोडता येत नाहीत (अनेक असंबंधित लोक ते वापरतात) &mdash; त्याऐवजी नेमका पत्ता विशिष्ट प्रेषक म्हणून जोडा.',
            'triage_heading' => 'ट्रायाज रांग &mdash; सुरक्षा जाळे',
            'triage_body' => 'शेअर्ड-इनटेक ईमेल कोणत्याही कंपनीशी जुळला नाही, तर तो हरवण्याऐवजी <strong>ट्रायाज</strong> मध्ये येतो (कंपनी स्विचरमधून, थेट संख्येसह). प्रत्येक नोंदीत प्रेषक, डोमेन, विषय आणि तो कोणत्या मेलबॉक्सवर आला ते दिसते. तो एकाच पायरीत कंपनीकडे नोंदवा:',
            'triage_create' => 'अस्तित्वातील कंपनी निवडा किंवा जागेवरच नवीन तयार करा.',
            'triage_assign' => 'सामान्य डोमेनसाठी, पर्यायाने <strong>ते डोमेन</strong> त्या कंपनीकडे राउट करा; सार्वजनिक/वेबमेल पत्त्यासाठी, पर्यायाने <strong>तो प्रेषक नेहमी</strong> तिथे नोंदवा.',
            'triage_sweep' => 'कोणताही पर्याय <em>स्वीप</em> करतो: त्या डोमेन किंवा पत्त्यावरील रांगेतील इतर सर्व ईमेलही हलवतो आणि पुढील मेल आपोआप राउट करतो &mdash; त्यामुळे एका प्रेषकाची वर्गवारी फक्त एकदाच करावी लागते.',
            'triage_tip' => 'काहीही कधीच हरवत नाही. जुळणी न झालेला मेल कोणी नोंदवेपर्यंत ट्रायाजमध्ये थांबतो; नोंदवलेले नसलेले तिकीट तोपर्यंत डीफॉल्ट कंपनी अंतर्गत दिसते.',
            'test_heading' => 'लाइव्ह जाण्यापूर्वी तुमचे राउटिंग तपासा',
            'test_body' => '<strong>सिस्टम &rarr; ईमेल राउटिंग चाचणी</strong> अंतर्गत तुम्ही ईमेल आल्याचे गृहीत धरू शकता &mdash; मेलबॉक्स निवडा, प्रेषक पत्ता टाका &mdash; आणि नवीन तिकीट नेमके कोणत्या कंपनीत जाईल (किंवा ट्रायाजमध्ये जाईल) आणि कोणत्या नियमाने ठरले ते पहा. यामुळे काहीही तयार होत नाही; ते फक्त तुमच्या सेटिंग्ज वाचते.',
            'settings_heading' => 'सेटिंग्ज: डीफॉल्टनुसार शेअर्ड, गरज असेल तिथे कस्टम',
            'settings_body' => 'यातील काही सेटिंग्ज <strong>प्रत्येक कंपनीनुसार बदलता येतात</strong>; इतर जाणीवपूर्वक शेअर्ड ठेवल्या आहेत. जिथे सेटिंग पर्यायांची साधी सूची आहे &mdash; जसे <strong>तिकीट प्रकार</strong> आणि <strong>स्रोत</strong> &mdash; तिथे कंपनीच्या संदर्भात स्विच करा; तुम्हाला शेअर्ड डीफॉल्ट (न वापरलेला पर्याय लपवण्यासाठी प्रत्येकासमोर डोळ्याचे आयकॉन) आणि त्या कंपनीने स्वतःसाठी जोडलेले पर्याय दिसतील. खुली तिकिटे अजून वापरत असताना तुम्ही पर्याय लपवू किंवा हटवू शकत नाही, आणि शेअर्ड डीफॉल्ट स्वतः MSP / डीफॉल्ट कंपनीतून संपादित केले जातात.',
            'settings_custom_title' => 'प्रत्येक कंपनीनुसार कस्टम',
            'settings_custom_body' => 'तिकीट प्रकार &amp; स्रोत (आता), आणि श्रेण्या, SLA &amp; कामाचे तास (लवकरच) &mdash; एका क्लायंटपासून दुसऱ्यापर्यंत खरोखर वेगळ्या असणाऱ्या गोष्टी.',
            'settings_global_title' => 'प्रत्येक कंपनीमध्ये शेअर्ड',
            'settings_global_body' => 'स्थिती आणि प्राधान्ये सर्वत्र सारखीच राहतात, त्यामुळे कंपन्यांमधील अहवाल आणि SLA एकसारखे राहतात; तुमचे संघ, रोटा आणि मेलबॉक्सही तसेच &mdash; ते तुमचे स्वतःचे कामकाज आहे, क्लायंटचे नाही.',
            'allview_heading' => '<strong>सर्व कंपन्यांसाठी एकच बोर्ड</strong>',
            'allview_body' => 'हेडरमधील कंपनी स्विचरमध्ये <strong>सर्व कंपन्या</strong> हा पर्याय आहे. तुम्हाला पाहण्याची परवानगी असलेले प्रत्येक तिकीट एकाच सूचीत दिसते, आणि प्रत्येक ओळीवर ते कोणत्या कंपनीचे आहे ते दिसते &mdash; तुम्ही अनेक संस्थांना सहाय्य करत असाल आणि कोणते कोणाचे हे न विसरता दिवसाचे एकच चित्र हवे असेल तेव्हा उपयुक्त.',
            'allview_card_scope_title' => 'हे काहीही नवीन अधिकार देत नाही',
            'allview_card_scope_body' => '"सर्व" म्हणजे तुम्ही आधीच एकेक करून पोहोचू शकत असलेल्या प्रत्येक कंपनीचे. तुमच्या तीनपैकी दोन संस्थांना सहाय्य करणारा विश्लेषक नेमक्या त्या दोनच पाहतो, आणि एका कंपनीचा विश्लेषक त्या एकाच कंपनीचे दृश्य पाहतो.',
            'allview_card_props_title' => 'प्रत्येक संस्था वेगळी राहते',
            'allview_card_props_body' => 'तिकीट उघडा आणि त्याचा प्रकार, स्रोत, श्रेणी आणि निराकरण सूची <em>त्या</em> कंपनीच्या असतात &mdash; त्यामुळे एका संस्थेकडे असलेली आणि दुसरीकडे नसलेली श्रेणी चुकीच्या तिकिटावर कधीच लागू होऊ शकत नाही.',
            'allview_card_new_title' => 'नवीन तिकिटे कोणती कंपनी ते विचारतात',
            'allview_card_new_body' => 'गृहीत धरण्यासाठी एकही सक्रिय कंपनी नसते, आणि ही निवड तिकीट क्रमांक, ज्या मेलबॉक्सवरून उत्तरे जातात तो आणि लागू होणारा SLA ठरवते. तुम्ही निवड केल्यावरच प्रकार सूची भरली जाते.',
            'allview_rule_chip' => 'ईमेल किंवा पोर्टलमार्फत आलेले पण अजून राउट न झालेले तिकीट डीफॉल्ट अंतर्गत दाखवण्याऐवजी <strong>अराउट</strong> म्हणून चिन्हांकित केले जाते, त्यामुळे ट्रायाजसाठी ते ठळक दिसते.',
            'allview_rule_reply' => 'उत्तरे अजूनही तिकीट ज्या मेलबॉक्सवर आले त्यातूनच जातात &mdash; ते तिकिटाला अनुसरते, दृश्याला नाही, त्यामुळे एकत्रित बोर्ड चुकीच्या पत्त्यावरून पाठवू शकत नाही.',
            'allview_rule_knowledge' => 'एकत्रित दृश्य चालू असताना <strong>AI ला विचारा</strong> फक्त एकच नव्हे, तर तुम्हाला दिसणाऱ्या प्रत्येक कंपनीमध्ये शोधते. सर्व कंपन्यांसोबत शेअर केलेले लेख दोन्ही बाबतीत समाविष्ट असतात.',
            'allview_rule_trash' => '<strong>कचरा रिकामा करणे कधीही कंपन्यांमध्ये पसरत नाही.</strong> तो नेहमी तुम्ही शेवटी निवडलेल्या एकाच कंपनीला लागू होतो, कारण एकाच वेळी अनेक संस्थांमधील "बिनमधले सर्व हटवा" असा कोणाचाही अर्थ नसतो.',
            'allview_rule_other' => 'फक्त तिकीट सूची रुंद होते. मालमत्ता, बदल, कार्ये आणि CMDB अजूनही एका वेळी एकच कंपनी दाखवतात &mdash; त्यात काम करण्यासाठी त्या कंपनीत स्विच करा.',
            'privacy_heading' => 'प्रत्येक कंपनीची तिकिटे खाजगी राहतात',
            'privacy_body' => 'तुम्ही एखाद्या कंपनीच्या संदर्भात काम करत असताना तुम्हाला फक्त <strong>त्या</strong> कंपनीची तिकिटे दिसतात &mdash; सूचीत, शोधात, डॅशबोर्डवर आणि तुम्ही उघडलेल्या प्रत्येक तिकिटावर (त्यातील ईमेल, जोडपत्रे, नोंदी आणि इतिहासासह). कर्मचाऱ्याला तिकिटाच्या कंपनीत प्रवेश दिला असेल तरच तो त्यापर्यंत पोहोचू शकतो (तुम्ही प्रत्येक विश्लेषकाच्या कंपन्या सिस्टम &rarr; विश्लेषक अंतर्गत निवडता, किंवा सिस्टम &rarr; संघ वर संपूर्ण संघाला देता), त्यामुळे दुसऱ्या क्लायंटच्या डेटामध्ये चुकून जाण्याचा मार्गच नाही. हे वेगळेपण केवळ दृश्यातून लपवलेले नसून पडद्यामागे सर्वत्र लागू केले जाते. एकाच कंपनीच्या इन्स्टॉलेशनवर ते आपोआप आणि अदृश्य असते &mdash; कंपनी एकच असल्याने सर्व काही तिचेच असते.',
            'tip' => 'एकाच कंपनीच्या इन्स्टॉलेशनवर यातले काहीही दिसत नाही &mdash; कंपनी एकच असते, प्रत्येक तिकीट तिचेच असते, आणि स्विचर किंवा ट्रायाज नसतो. दुसरी कंपनी अस्तित्वात आल्यावरच ही वैशिष्ट्ये सुरू होतात.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'SLA व्यवस्थापन',
        'back_link' => '&larr; तिकिटे मार्गदर्शकाकडे परत',
        'sidebar_title' => 'SLA मार्गदर्शक',
        'hero_title' => 'SLA व्यवस्थापन',
        'hero_sub' => 'कामकाजाच्या तासांनुसार प्रतिसाद आणि निराकरणाची लक्ष्ये, विभागानुसार उल्लंघन सूचनांसह',
        'nav' => [
            'overview' => 'आढावा',
            'building_blocks' => 'मूलभूत घटक',
            'behaviour_settings' => 'वर्तन सेटिंग्ज',
            'breach_notifications' => 'उल्लंघन सूचना',
            'cron_setup' => 'Cron जॉब सेटअप',
            'worked_examples' => 'उदाहरणे',
            'troubleshooting' => 'समस्यानिवारण',
        ],
        'overview' => [
            'heading' => 'आढावा',
            'sub' => 'SLA म्हणजे काय, ते का महत्त्वाचे आहेत आणि FreeITSM इंजिन सर्वसाधारणपणे कसे काम करते.',
            'p1' => 'सर्व्हिस लेव्हल अ‍ॅग्रीमेंट (SLA) म्हणजे तुमचा संघ तिकिटाला किती लवकर प्रतिसाद देईल आणि ते किती लवकर सोडवेल याचे वचन. FreeITSM प्रत्येक तिकिटासाठी दोन घड्याळे मोजते: <strong>प्रतिसाद</strong> (तिकीट तयार झाल्यापासून विश्लेषकाच्या पहिल्या कृतीपर्यंतचा वेळ) आणि <strong>निराकरण</strong> (तिकीट तयार झाल्यापासून ते बंद होईपर्यंतचा वेळ). दोन्ही लक्ष्ये प्राधान्यानुसार ठरवली जातात &mdash; त्यामुळे P1 साठी प्रतिसादाला 30 मिनिटे आणि निराकरणाला 4 तास असू शकतात, तर P4 साठी 8 कामकाजाचे तास आणि 5 कामकाजाचे दिवस असू शकतात.',
            'p2' => 'FreeITSM च्या SLA इंजिनमध्ये चार रचनात्मक निवडी समजून घेण्यासारख्या आहेत:',
            'choice_business' => '<strong>कामकाजाचे तास, भिंतीवरचे घड्याळ नव्हे.</strong> संध्याकाळी 4:30 वाजता नोंदवलेले, 1 तासाचे प्रतिसाद लक्ष्य असलेले P2 तिकीट, कार्यालय 5 वाजता बंद होत असल्यास 5:30 वाजता उल्लंघन करत नाही. घड्याळ पुढच्या कामकाजाच्या दिवशी सकाळी 9 वाजता पुन्हा सुरू होते. हेच उद्योग मानक आहे आणि विश्लेषक रात्री घरी जात असताना हाच एकमेव न्याय्य मार्ग आहे.',
            'choice_pause' => '<strong>थांबवता येणारे.</strong> तिकीट "SLA थांबवा" म्हणून चिन्हांकित केलेल्या स्थितीत (उदा. <em>प्रतिसादाची प्रतीक्षा</em> किंवा <em>होल्डवर</em>) असताना घड्याळ थांबते. तिकीट पुन्हा कामाच्या स्थितीत गेल्यावर ते पुन्हा सुरू होते.',
            'choice_compute' => '<strong>वाचताना गणना, साठवलेली नाही.</strong> तुम्ही प्रत्येक वेळी पाहता तेव्हा इंजिन तिकिटाच्या ऑडिट लॉगमधून SLA स्थिती पुन्हा मोजते. असंगत होऊ शकणारे कोणतेही साठवलेले काउंटर नाहीत. नंतर तुम्ही एखाद्या कामकाज दिनदर्शिकेचे तास बदलले, तर प्रत्येक जुन्या तिकिटाचा SLA पुढच्या वेळी पाहिल्यावर नवीन तासांनुसार पुन्हा मोजला जातो.',
            'choice_cutoff' => '<strong>अंमलबजावणीची कट-ऑफ तारीख.</strong> प्रशासकाने नियंत्रित केलेली "SLA यापासून लागू करा" तारीख म्हणजे SLA सुरू केल्यावर तुमच्या सिस्टममधील जुनी तिकिटे अचानक मागील तारखेपासून उल्लंघनात जात नाहीत. फक्त कट-ऑफच्या दिवशी किंवा त्यानंतर तयार झालेल्या तिकिटांचा मागोवा घेतला जातो.',
            'tip' => 'तुम्ही ITIL मध्ये नवीन असाल तर: प्रतिसाद वेळ म्हणजे पोचपावती (कोणीतरी ते हाती घेतले); निराकरण वेळ म्हणजे पूर्णत्व (वापरकर्त्याची समस्या दुरुस्त झाली). दोन्ही घड्याळे स्वतंत्रपणे चालतात आणि त्यांची लक्ष्ये वेगळी असतात.',
        ],
        'blocks' => [
            'heading' => 'चार मूलभूत घटक',
            'sub' => 'या चार गोष्टी कॉन्फिगर करा आणि SLA ट्रॅकिंग सुरू होते. बाकी सर्व पर्यायी सुधारणा आहेत.',
            'cal_heading' => '1. कामकाज दिनदर्शिका',
            'cal_intro' => 'दिनदर्शिका तुमचा सर्व्हिस डेस्क कधी उघडा असतो ते ठरवते. प्रत्येक दिनदर्शिकेत हे असते:',
            'cal_tz' => '<strong>टाइमझोन</strong> &mdash; IANA टाइमझोन ओळखकर्ता (उदा. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). DST बदल आपोआप हाताळले जातात.',
            'cal_hours' => '<strong>साप्ताहिक कामाचे तास</strong> &mdash; प्रत्येक वारासाठी एक ओळ, ज्यात उघडा चेकबॉक्स आणि सुरुवात / शेवटच्या वेळा असतात. नवीन दिनदर्शिका सोम-शुक्र 09:00-17:00 अशी डीफॉल्ट असते, शनि/रवि बंद. उघडा म्हणून चिन्हांकित नसलेली ओळ म्हणजे त्या दिवशी डेस्क बंद आहे.',
            'cal_holidays' => '<strong>सुट्ट्या</strong> &mdash; तारीख + पर्यायी नाव. सुट्ट्या साप्ताहिक आराखड्याला ओव्हरराइड करतात (सुट्टी सोमवारी आली तरी डेस्क बंद असतो).',
            'cal_default' => '<strong>डीफॉल्ट ध्वज</strong> &mdash; नेमकी एकच दिनदर्शिका डीफॉल्ट असते. वेगळे नमूद केल्याशिवाय नवीन प्राधान्ये ती वारसाने घेतात.',
            'cal_outro' => 'तुम्हाला हव्या तितक्या दिनदर्शिका तयार करता येतात &mdash; प्रत्येक कार्यालयासाठी एक, प्रत्येक संघासाठी एक, वाढीव तास असलेल्या VIP ग्राहकांसाठी एक. त्या SLA लक्ष्ये आणि उल्लंघन-तपासणी इंजिन यांच्यात सामायिक असतात.',
            'prio_heading' => '2. SLA लक्ष्यांसह प्राधान्ये',
            'prio_intro' => 'प्राधान्ये टॅबवर (किंवा SLA टॅबवरील SLA लक्ष्ये तक्त्याद्वारे) प्रत्येक प्राधान्याला हे असू शकते:',
            'prio_response' => '<strong>प्रतिसाद लक्ष्य (मिनिटे)</strong> &mdash; विश्लेषकाच्या पहिल्या कृतीपर्यंत किती वेळ.',
            'prio_resolution' => '<strong>निराकरण लक्ष्य (मिनिटे)</strong> &mdash; तिकीट बंद होईपर्यंत किती वेळ.',
            'prio_calendar' => '<strong>दिनदर्शिका</strong> &mdash; या प्राधान्याचे घड्याळ कोणत्या कामकाज दिनदर्शिकेनुसार चालते. डीफॉल्ट दिनदर्शिका वापरण्यासाठी रिकामे सोडा.',
            'prio_outro' => 'दोन्ही लक्ष्य फील्ड रिकामी ठेवल्यास त्या प्राधान्यासाठी SLA ट्रॅकिंग पूर्णपणे बंद होते &mdash; वेळेचा दबाव नसलेल्या "माहितीपर" किंवा "बॅकलॉग" प्राधान्यासाठी उपयुक्त.',
            'pause_heading' => '3. SLA थांबवणाऱ्या स्थिती',
            'pause_intro' => 'स्थिती टॅबवर "SLA थांबवा" नावाचा स्वतंत्र कॉलम आहे. संघाच्या नियंत्रणाबाहेरील एखाद्या गोष्टीवर तिकीट अडकले आहे हे दर्शवणारी कोणतीही स्थिती चिन्हांकित करा. सर्वसाधारण उदाहरणे:',
            'pause_awaiting' => '<strong>प्रतिसादाची प्रतीक्षा</strong> &mdash; ग्राहकाकडून आम्हाला माहिती हवी आहे. थांबवण्याचे जवळजवळ सर्वत्र मान्य न्याय्य कारण.',
            'pause_vendor' => '<strong>होल्डवर (विक्रेता)</strong> &mdash; Microsoft / तृतीय-पक्ष सपोर्टची प्रतीक्षा.',
            'pause_change' => '<strong>होल्डवर (बदल विंडो)</strong> &mdash; भविष्यातील देखभाल विंडोसाठी नियोजित.',
            'pause_parts' => '<strong>होल्डवर (पार्ट्स)</strong> &mdash; हार्डवेअर येण्याची प्रतीक्षा.',
            'pause_warn' => 'तिकीट अवघड असताना किंवा विश्लेषक व्यस्त असताना सामान्य "होल्डवर" स्थितीचा SLA मधून सुटण्यासाठी गैरवापर होऊ शकतो. तुमच्या संघात शिस्त असेल तर हे ठीक आहे. नसेल तर वरील अधिक विशिष्ट प्रकारांनी ती बदलण्याचा विचार करा, किंवा 24 तासांहून जास्त काळ थांबलेल्या तिकिटांना पिवळ्या इशाऱ्याने दाखवणाऱ्या <strong>Watchtower</strong> डॅशबोर्डवर अवलंबून राहा.',
            'cutoff_heading' => '4. अंमलबजावणी कट-ऑफ (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'सर्वात महत्त्वाची एकमेव जागतिक सेटिंग. येथे तारीख-वेळ सेट करेपर्यंत SLA ट्रॅकिंग पूर्णपणे बंद असते &mdash; कोणतीही घड्याळे चालत नाहीत, इनबॉक्सवर कोणतेही पिल दिसत नाहीत, उल्लंघनाचे ईमेल जात नाहीत. भूतकाळातील तारीख-वेळ दिल्यास त्या क्षणापासून SLA मागील तारखेपासून सुरू होतात. भविष्यातील तारीख-वेळ दिल्यास सुरू होण्याची वेळ ठरते.',
            'cutoff_p2' => 'बहुतेक संघ SLA पहिल्यांदा सुरू करताना हे "आत्ता" वर सेट करतात &mdash; जुनी तिकिटे SLA-पूर्वीच्या स्थितीत राहतात, त्या क्षणानंतरच्या नवीन तिकिटांचा मागोवा घेतला जातो.',
        ],
        'behaviour' => [
            'heading' => 'वर्तन सेटिंग्ज',
            'sub' => 'अपवादात्मक प्रसंगांना इंजिन कसा प्रतिसाद देते ते यातून नियंत्रित होते. डीफॉल्ट योग्य आहेत &mdash; तुमची विशिष्ट पसंती असेल तरच ते पुन्हा पाहावे लागतात.',
            'prio_heading' => 'मध्येच प्राधान्य बदलल्यावर',
            'prio_intro' => 'P3 तिकीट मध्यावर P1 मध्ये वाढवले गेले (कारण समस्या वाटली त्यापेक्षा मोठी निघाली), तर तीन योग्य वर्तने आहेत:',
            'prio_forward' => '<strong>पुढे (डीफॉल्ट)</strong> &mdash; जमा झालेली कामकाजाची मिनिटे जपून ठेवते आणि फक्त नवे लक्ष्य लावते. तिकिटाने त्याच्या 8 तासांच्या P3 लक्ष्यापैकी 2 तास वापरले असतील, तर आता 1 तासाच्या P1 लक्ष्याविरुद्ध 2 तास वापरले गेले आहेत &mdash; म्हणजे ते आधीच उल्लंघनात आहे. हे एका अर्थाने बरोबर आहे: समस्या सुरुवातीपासून P1 च होती, संघाला फक्त ते कळले नव्हते.',
            'prio_recompute' => '<strong>पुन्हा मोजा</strong> &mdash; घड्याळ रीसेट करून नवे लक्ष्य तिकीट तयार झाल्यापासून मागील तारखेपासून लागू करते. स्वच्छ पुनर्गणना.',
            'prio_reset' => '<strong>रीसेट</strong> &mdash; प्राधान्य बदलल्याच्या क्षणापासून नवे घड्याळ सुरू करते. संघासाठी सर्वात सोयीचे, पण उच्च-प्राधान्य तिकिटाला अचानक नवे लांब घड्याळ मिळाले तर ग्राहकांना फसवल्यासारखे वाटू शकते.',
            'reopen_heading' => 'बंद तिकीट पुन्हा उघडल्यावर',
            'reopen_intro' => 'तिकीट पुन्हा उघडले गेल्यास (बंद झाल्यानंतर वापरकर्त्याने उत्तर दिल्यास):',
            'reopen_reset' => '<strong>रीसेट (डीफॉल्ट)</strong> &mdash; पुन्हा उघडल्याच्या क्षणापासून नवे प्रतिसाद आणि निराकरण घड्याळ सुरू करते. पुन्हा उघडणे म्हणजे प्रत्यक्षात नवे तिकीट मानते.',
            'reopen_continue' => '<strong>सुरू ठेवा</strong> &mdash; बंद होताना झालेल्या वेळेपासून पुढे चालू ठेवते. मूळ SLA लक्ष्ये लागू राहतात.',
            'first_heading' => 'पहिल्या प्रतिसादाची व्याख्या',
            'first_intro' => '"पहिला प्रतिसाद" म्हणजे काय &mdash; प्रतिसाद घड्याळ थांबवणारा क्षण कोणता?',
            'first_either' => '<strong>कोणताही (डीफॉल्ट)</strong> &mdash; कोणत्याही प्रकारची विश्लेषकाची पहिली कृती: जाणारा ईमेल, स्थिती बदल, नेमणूक.',
            'first_status' => '<strong>स्थिती बदल</strong> &mdash; डीफॉल्ट स्थितीपासून दूर जाणारा स्थिती बदलच ग्राह्य धरला जातो. अधिक कडक &mdash; विश्लेषकाने तिकिटावर प्रत्यक्ष काम केलेले असावे लागते, फक्त ते उघडून पाहिलेले नको.',
            'first_email' => '<strong>जाणारा ईमेल</strong> &mdash; फक्त विनंती करणाऱ्याला दिलेले ईमेल उत्तरच ग्राह्य धरले जाते. सर्वात कडक &mdash; ग्राहकाला आमच्याकडून उत्तर मिळालेले असावे लागते.',
            'warn_heading' => 'इशारा मर्यादा टक्केवारी',
            'warn_body' => 'निर्देशक हिरव्यावरून पिवळ्यावर बदलण्यापूर्वी SLA लक्ष्याचा किती भाग संपलेला असतो. डीफॉल्ट 80% आहे &mdash; त्यामुळे 60 मिनिटांचे प्रतिसाद लक्ष्य 48 मिनिटे उलटल्यावर पिवळे दिसते. इशारा-ट्रिगर उल्लंघन सूचनाही यावरून ठरतात.',
        ],
        'breach' => [
            'heading' => 'उल्लंघन सूचना',
            'sub' => 'SLA उल्लंघनाच्या जवळ आल्यावर (इशारा) किंवा प्रत्यक्ष उल्लंघन झाल्यावर जाणारे, विभागानुसार कॉन्फिगर करता येणारे ईमेल नियम.',
            'intro' => 'प्रत्येक नियमाला चार परिमाणे असतात, सर्व स्वतंत्र:',
            'scope_heading' => '1. व्याप्ती',
            'scope_body' => '<strong>डीफॉल्ट</strong> (नियम प्रत्येक विभागातील तिकिटांना लागू होतो) किंवा <strong>विशिष्ट विभाग</strong>. निर्णय: त्या विभागातील तिकिटांसाठी विभाग-विशिष्ट नियम डीफॉल्टपेक्षा वरचढ ठरतो. डीफॉल्ट नियम नसेल, तर विशिष्ट नियम नसलेल्या विभागांना कोणत्याही सूचना मिळत नाहीत.',
            'trigger_heading' => '2. ट्रिगर',
            'trigger_body' => '<strong>इशारा</strong> (तिकिटाने इशारा मर्यादा ओलांडली आहे &mdash; संभाव्य उल्लंघन) किंवा <strong>उल्लंघन</strong> (तिकिटाने लक्ष्य ओलांडले आहे &mdash; प्रत्यक्ष उल्लंघन). प्रत्येकाचा स्वतःचा नियम असतो, त्यामुळे दोन्हींसाठी वेगवेगळ्या लोकांना सूचित करता येते.',
            'target_heading' => '3. लक्ष्य',
            'target_body' => 'कोणते घड्याळ पाहायचे &mdash; <strong>प्रतिसाद</strong>, <strong>निराकरण</strong> किंवा <strong>दोन्ही</strong>.',
            'recip_heading' => '4. प्राप्तकर्ते',
            'recip_intro' => 'खालीलपैकी कोणताही संयोग:',
            'recip_assignee' => '<strong>तिकिटाचा नियुक्त विश्लेषक</strong> &mdash; सध्या तिकीट सांभाळणारा विश्लेषक. नेमणूक नसल्यास वगळला जातो.',
            'recip_teams' => '<strong>तिकिटाच्या विभागाच्या संघांचे सदस्य</strong> &mdash; तिकिटाच्या विभागाशी जोडलेल्या कोणत्याही संघातील प्रत्येक विश्लेषक. वितरण यादी सांभाळल्याशिवाय संपूर्ण रांग कव्हर होते.',
            'recip_specific' => '<strong>एक विशिष्ट विश्लेषक</strong> &mdash; "SLA चॅम्पियन" / "सेवा व्यवस्थापक" पद्धत, जिथे भूमिकेऐवजी नाव असलेली व्यक्ती असते.',
            'recip_custom' => '<strong>सानुकूल ईमेल पत्ते</strong> &mdash; स्वल्पविरामाने वेगळे केलेला मुक्त मजकूर. शेअर्ड इनबॉक्स (<code>sla-alerts@company.com</code>), Slack/Teams ईमेल ब्रिज किंवा वितरण याद्यांसाठी उपयुक्त.',
            'tip' => 'प्रत्येक तिकीट प्रत्येक (लक्ष्य, ट्रिगर) साठी जास्तीत जास्त एकच ईमेल पाठवते &mdash; cron वर्कर काय पाठवले गेले ते <code>sla_notifications_sent</code> टेबलमध्ये नोंदवतो. म्हणजे इशारा एकदाच जातो, उल्लंघन एकदाच जाते, बस्स &mdash; ईमेलचा भडिमार होत नाही.',
            'warn' => '<strong>नियम नाहीत = ईमेल नाहीत.</strong> सिस्टममधील प्रत्येक तिकिटाने उल्लंघन केले तरी तुम्ही किमान एक नियम जोडेपर्यंत काहीही जात नाही. सर्व काही कव्हर करण्यासाठी डीफॉल्ट-व्याप्तीची इशारा + उल्लंघन जोडी घेऊन सुरुवात करा.',
        ],
        'cron' => [
            'heading' => 'Cron जॉब सेट करणे',
            'sub' => 'उल्लंघन-तपासणी स्क्रिप्ट वेळापत्रकानुसार चालवावी लागते. दर 5 मिनिटांनी एकदा हा योग्य अंतराल आहे.',
            'p1' => 'UI मध्ये दिसणारे SLA निर्देशक (इनबॉक्सवरील पिल, रीडिंग पेनमधील पॅनेल) पृष्ठ लोड होताना त्याच क्षणी मोजले जातात. पण कोणीही पाहत नसतानाही <em>कोणीतरी</em> तिकिटे तपासत असेल तरच उल्लंघनाचे ईमेल जाऊ शकतात. ते "कोणीतरी" म्हणजे शेड्यूल केलेले कार्य &mdash; Windows वर Task Scheduler; Linux वर cron.',
            'p2' => 'स्क्रिप्ट FreeITSM इन्स्टॉल डायरेक्टरीमध्ये <code>cron/sla_breach_check.php</code> आहे. ती दोन प्रकारे चालवता येते:',
            'cli_heading' => 'A. CLI (तुमच्या नियंत्रणातील सर्व्हरवर शिफारस केलेले)',
            'cli_note' => 'प्रमाणीकरण आवश्यक नाही &mdash; ती कोण चालवू शकते हे फाइलसिस्टम परवानग्याच ठरवतात.',
            'http_heading' => 'B. HTTP (शेअर्ड होस्टिंग किंवा रिमोट शेड्यूलरसाठी)',
            'http_note' => 'टोकन पहिल्या इन्स्टॉलच्या वेळी आपोआप तयार होते आणि <code>system_settings</code> मध्ये <code>sla_cron_token</code> या की खाली साठवले जाते (32 हेक्स अक्षरे, ~128 बिट एन्ट्रॉपी). ते साठवणुकीत एन्क्रिप्टेड असते, त्यामुळे ती ओळ थेट वाचल्यास टोकनऐवजी <code>ENC:…</code> दिसते. तुमचे टोकन असे शोधा:',
            'win_heading' => 'Windows Task Scheduler',
            'win_intro' => 'Task Scheduler (<code>taskschd.msc</code>) उघडा आणि या सेटिंग्जसह नवे कार्य तयार करा:',
            'tbl_field' => 'फील्ड',
            'tbl_value' => 'मूल्य',
            'win_r1_k' => 'नाव',
            'win_r1_v' => 'FreeITSM &mdash; SLA उल्लंघन तपासणी',
            'win_r2_k' => 'वापरकर्ता लॉग इन असो वा नसो चालवा',
            'win_r2_v' => 'हे टिक करा',
            'win_r3_k' => 'ट्रिगर',
            'win_r3_v' => 'दैनिक, दर 1 दिवसाने पुनरावृत्ती, 1 दिवसासाठी दर 5 मिनिटांनी पुन्हा चालवा',
            'win_r4_k' => 'क्रिया',
            'win_r4_v' => 'प्रोग्राम सुरू करा',
            'win_r5_k' => 'प्रोग्राम/स्क्रिप्ट',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'आर्ग्युमेंट्स जोडा',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'यामध्ये सुरू करा',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'तुमच्या crontab मध्ये (<code>crontab -e</code>) एक ओळ जोडा:',
            'sec_heading' => 'सुरक्षा &mdash; HTTP एंडपॉइंटचे संरक्षण कशाने होते',
            'sec_intro' => 'तीन स्तर, सर्व आपोआप लागू होतात:',
            'sec_token' => '<strong>1. शेअर्ड-सिक्रेट टोकन</strong> &mdash; प्रत्येक इन्स्टॉलसाठी 128-बिट यादृच्छिक, टायमिंग हल्ले टाळण्यासाठी कॉन्स्टंट-टाइम तुलनेने जुळवले जाते.',
            'sec_lockout' => '<strong>2. प्रति-IP अयशस्वी प्रमाणीकरण लॉकआउट</strong> &mdash; एकाच IP वरून गेल्या तासात 10 पेक्षा जास्त चुकीची टोकन प्रयत्ने झाल्यास 1 तासाचा 429 लॉकआउट लागू होतो. fail2ban शिवाय ब्रूट-फोर्स प्रयत्न निष्फळ ठरतात.',
            'sec_interval' => '<strong>3. यशस्वी चालवण्यांमधील किमान अंतर</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (डीफॉल्ट 30s). वैध टोकन असलेली विनंतीही मागील यशस्वी चालवण्यानंतर यापेक्षा लवकर आली तर तिला 429 मिळतो. चुकून दुहेरी शेड्यूल होणे आणि अनियंत्रित लूप टाळले जातात.',
            'log_heading' => 'क्रियाकलाप नोंद',
            'log_body' => 'प्रत्येक चालवणी (स्वीकारलेली किंवा नाकारलेली) वेळ, निकाल, संख्या आणि क्लायंट IP सह <code>sla_cron_runs</code> टेबलमध्ये नोंदवली जाते. शेवटच्या 20 चालवण्या SLA सेटिंग्ज टॅबच्या तळाशी असलेल्या <strong>Cron क्रियाकलाप</strong> पॅनेलमध्ये पाहा &mdash; शेड्यूल चालू आहे याची खात्री करण्यासाठी आणि अयशस्वी प्रमाणीकरण प्रयत्नांची तपासणी करण्यासाठी उपयुक्त. <code>sla_cron_log_retention_days</code> (डीफॉल्ट 30) नंतर ओळी आपोआप काढल्या जातात, त्यामुळे टेबल लहान राहते.',
        ],
        'examples' => [
            'heading' => 'प्रत्यक्ष उदाहरणे',
            'sub' => 'एकाच टाइमझोनच्या सोप्या प्रकरणापासून "न्याय्य" म्हणजे काय हे ठरवावे लागणाऱ्या अवघड, अनेक टाइमझोनच्या प्रकरणापर्यंत.',
            'ex1_heading' => 'उदाहरण 1: तिकीट UK मध्ये नोंदवले, सर्व्हिस डेस्क UK मध्ये',
            'ex1_title' => 'सोपे प्रकरण',
            'ex1_tag' => 'एकच टाइमझोन',
            'ex1_setup' => '<strong>सेटअप:</strong> <em>UK Office</em> नावाची एक व्यवसाय दिनदर्शिका, टाइमझोन <code>Europe/London</code>, सोम-शुक्र 09:00-17:00, सुट्ट्या नाहीत. P2 प्राधान्याला 1 तासाचे प्रतिसाद लक्ष्य आणि 4 तासांचे निराकरण लक्ष्य आहे, दोन्ही <em>UK Office</em> दिनदर्शिकेनुसार चालतात.',
            'ex1_scenario' => '<strong>परिस्थिती:</strong> वापरकर्ता <strong>बुधवारी UK वेळेनुसार 16:30 वाजता</strong> P2 तिकीट नोंदवतो.',
            'ex1_timeline' => 'बुध 16:30 UK &mdash; <strong>तिकीट तयार झाले</strong>, प्रतिसादाचे घड्याळ सुरू होते.
बुध 17:00 UK &mdash; कार्यालय बंद होते, घड्याळ थांबते (60 मिनिटांच्या लक्ष्यापैकी 30 मिनिटे वापरली).
गुरु 09:00 UK &mdash; कार्यालय उघडते, घड्याळ पुन्हा सुरू होते.
गुरु 09:30 UK &mdash; विश्लेषक उत्तर देतो. प्रतिसाद SLA अगदी वेळेवर पूर्ण झाला (60 मिनिटे वापरली, लक्ष्य 60 मिनिटे).',
            'ex1_outro' => 'विश्लेषकाने <strong>गुरुवारी 10:00 UK</strong> पर्यंत उत्तर दिले नसते, तर प्रतिसादाचा <strong>30 मिनिटांनी भंग झाला असता</strong> (60 मिनिटांच्या लक्ष्याच्या तुलनेत 90 मिनिटे वापरली &mdash; बुधवार संध्याकाळची 30 आणि गुरुवार सकाळची 60). 1 तासाचे घड्याळ फक्त कामाच्या वेळेत चालते, पण दिवसाच्या शेवटी आलेले तिकीट कार्यालय पुन्हा उघडेपर्यंत रात्रभरात आपला बराचसा वेळ गमावते &mdash; 09:00 वाजता येणाऱ्या विश्लेषकाला पूर्ण तास मिळाला आहे असे वाटणे सोपे आहे, पण प्रत्यक्षात फक्त 30 मिनिटेच उरलेली असतात.',
            'ex2_heading' => 'उदाहरण 2: तिकीट UK मध्ये नोंदवले, सर्व्हिस डेस्क एस्टोनियामध्ये',
            'ex2_title' => 'अनेक टाइमझोनचे प्रकरण',
            'ex2_tag' => '"न्याय्य" ठरवण्याचे 3 मार्ग',
            'ex2_setup' => '<strong>सेटअप:</strong> UK मधील ग्राहक (<code>Europe/London</code>, GMT/BST), एस्टोनियातील सर्व्हिस डेस्क (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>UK पेक्षा 2 तास पुढे</strong>). दोन्ही डेस्क नेहमी स्थानिक वेळेनुसार 09:00-17:00 काम करतात.',
            'ex2_scenario' => '<strong>परिस्थिती:</strong> UK ग्राहक <strong>शुक्रवारी UK वेळेनुसार 16:30 वाजता</strong> P2 तिकीट नोंदवतो (= एस्टोनियात 18:30, एस्टोनियाचे कामकाज संपल्यानंतर). एस्टोनियातील विश्लेषकाला त्यावर काम करण्याची पुढील संधी सोमवारी एस्टोनियात 09:00 (= UK मध्ये 07:00) आहे. प्रतिसाद लक्ष्य 1 तास आहे.',
            'ex2_question' => 'SLA काय सांगावे? तीन समर्थनीय उत्तरे आहेत, प्रत्येक वेगळ्या अर्थाने न्याय्य. तुमचा सेवा करार काय वचन देतो त्यानुसार प्राधान्यासाठी कोणती दिनदर्शिका द्यायची ते तुम्ही ठरवता.',
            'optA_label' => 'पर्याय A &mdash; ग्राहक-केंद्रित',
            'optA_p1' => '<strong>प्राधान्यासाठी <em>UK</em> वेळेची दिनदर्शिका वापरा.</strong> विश्लेषक कुठेही असला तरी घड्याळ UK 09:00-17:00 नुसार चालते.',
            'optA_p2' => 'वरील परिस्थितीत, तिकीट शुक्रवारी UK 16:30 ला नोंदवले: घड्याळ शुक्रवारी UK 16:30&ndash;17:00 चालते (30 मिनिटे वापरली), रात्रभर आणि आठवड्याच्या शेवटी थांबते, सोमवारी UK 09:00 ला पुन्हा सुरू होते. एस्टोनियातील विश्लेषकाने सोमवारी एस्टोनियात 10:00 ला (= UK मध्ये 08:00) उत्तर दिले, तरीही UK दिनदर्शिका थांबलेलीच असते (UK कार्यालय UK 09:00 ला उघडते), त्यामुळे अतिरिक्त मिनिटे जात नाहीत &mdash; वापर 30 मिनिटेच राहतो. <strong>SLA 30 मिनिटांच्या फरकाने पूर्ण झाला</strong>. UK 09:30 (= एस्टोनियात 11:30) नंतरचे कोणतेही उत्तर भंग ठरेल.',
            'optA_p3' => '<em>यांच्यासाठी न्याय्य:</em> ग्राहक. त्यांचा अनुभव त्यांच्या कामाच्या दिवसाशी जुळतो.<br><em>तडजोड:</em> एस्टोनियातील विश्लेषकांनी UK वेळेनुसार 09:00-17:00 (= एस्टोनियात 11:00-19:00) उपलब्ध असणे अपेक्षित आहे, त्यामुळे त्यांचा कामाचा दिवस 2 तासांनी वाढतो.',
            'optB_label' => 'पर्याय B &mdash; विश्लेषक-केंद्रित',
            'optB_p1' => '<strong>प्राधान्यासाठी <em>एस्टोनिया</em> वेळेची दिनदर्शिका वापरा.</strong> घड्याळ एस्टोनिया 09:00-17:00 नुसार चालते.',
            'optB_p2' => 'तीच परिस्थिती: तिकीट शुक्रवारी एस्टोनियात 18:30 ला (कामकाज संपल्यानंतर) नोंदवले, घड्याळ आठवड्याच्या शेवटी थांबलेले, सोमवारी एस्टोनियात 09:00 ला (= UK मध्ये 07:00) चालू होते. विश्लेषकाने सोमवारी एस्टोनियात 09:30 ला (= UK मध्ये 07:30) प्रतिसाद दिला, तर प्रतिसाद SLA ने 60 मिनिटांच्या लक्ष्यापैकी 30 मिनिटे वापरली आहेत &mdash; <strong>30 मिनिटांच्या फरकाने पूर्ण</strong>. UK ग्राहकाने शुक्रवारी UK 16:30 ला नोंदवले आणि सोमवारी UK 07:30 ला उत्तर मिळाले &mdash; त्यांची प्रत्यक्ष घड्याळी प्रतीक्षा SLA सुचवते त्यापेक्षा बरीच जास्त होती.',
            'optB_p3' => '<em>यांच्यासाठी न्याय्य:</em> विश्लेषक. ते नेहमीच्या वेळेत काम करतात.<br><em>तडजोड:</em> शुक्रवारी दुपारी नोंदवलेल्या तिकिटाची दखल सोमवारी सकाळी एस्टोनियाच्या वेळेपर्यंत घेतली जात नसेल, पण अहवालात प्रतिसाद SLA 1 तास दिसत असेल, तर UK मधील ग्राहकांना SLA "खोटे बोलत आहे" असे वाटू शकते. तुमच्या सेवा कराराने SLA सपोर्ट-डेस्कच्या वेळेनुसार चालतो हे स्पष्टपणे नमूद केले आहे याची खात्री करा.',
            'optC_label' => 'पर्याय C &mdash; ओव्हरलॅप विंडो (सर्वात कठोर)',
            'optC_p1' => '<strong>प्राधान्यासाठी फक्त दोन्ही डेस्क उघडे असतात त्या वेळा व्यापणारी दिनदर्शिका वापरा.</strong> UK 09:00-17:00 आणि एस्टोनिया 09:00-17:00 (= UK 07:00-15:00) हे <strong>UK 09:00-15:00 या विंडोमध्ये</strong> एकमेकांवर येतात &mdash; प्रत्येक कामकाजाच्या दिवशी 6 तास.',
            'optC_p2' => 'तीच परिस्थिती: तिकीट शुक्रवारी UK 16:30 ला नोंदवले (ओव्हरलॅपच्या बाहेर, कारण ओव्हरलॅप UK 15:00 ला संपतो), घड्याळ आठवड्याच्या शेवटी थांबलेले, सोमवारी UK 09:00 ला (= एस्टोनियात 11:00, ओव्हरलॅप पुन्हा सुरू होण्याच्या क्षणी) पुन्हा सुरू होते. एस्टोनियातील विश्लेषकाने एस्टोनियात 11:30 ला (= UK मध्ये 09:30) उत्तर दिले, तर प्रतिसाद SLA ने 60 मिनिटांच्या लक्ष्यापैकी 30 मिनिटे वापरली आहेत &mdash; <strong>30 मिनिटांच्या फरकाने पूर्ण</strong>. उत्तर ओव्हरलॅप विंडोमध्ये दिले गेले, म्हणून ते लगेच मोजले जाते.',
            'optC_p3' => '<em>यांच्यासाठी न्याय्य:</em> दोन्ही बाजू &mdash; SLA फक्त अशा वेळीच चालतो जेव्हा डेस्क तिकिटावर प्रत्यक्ष प्रगती करू शकतो आणि प्रतिसाद स्वीकारण्यासाठी ग्राहकही त्यांच्या डेस्कवर असतो.<br><em>तडजोड:</em> दैनंदिन विंडो लहान असल्याने कडक लक्ष्ये पूर्ण करण्यासाठी प्रत्यक्ष घड्याळी वेळ जास्त लागतो. 4 तासांचे निराकरण लक्ष्य ओव्हरलॅपच्या 1.5 दिवसांमध्ये पसरते, तर नेहमीच्या 8 तासांच्या दिनदर्शिकेत ते एका दिवसातच पूर्ण झाले असते.',
            'choose_tip' => '<strong>कसे निवडावे:</strong> तुमचा सेवा करार पाहा. त्यात "मिळाल्यापासून 1 तासाच्या आत प्रतिसाद" असे असेल &mdash; तर तो पर्याय A (ग्राहकाचे घड्याळ) आहे. "1 कामकाजी तासाच्या आत प्रतिसाद" असे असेल &mdash; तर तो सहसा पर्याय B (जो डेस्क काम करत आहे तो) असतो. "परस्पर उपलब्धतेच्या 1 तासाच्या आत" असे असेल &mdash; तर तो पर्याय C आहे. करार नसेल, तर संघाला विचारा: एस्टोनियाच्या वेळेबाहेरही तुम्हाला दबाव हवा आहे (पर्याय A), की UK ग्राहकांना कधीकधी दुर्लक्षित वाटले तरी चालेल (पर्याय B)?',
            'ex3_heading' => 'उदाहरण 3: विक्रेत्याच्या प्रतीक्षेदरम्यान घड्याळ थांबवणे',
            'ex3_title' => 'थांबवण्याच्या स्थिती प्रत्यक्षात कशा चालतात',
            'ex3_tag' => 'घड्याळ थांबवणे',
            'ex3_setup' => '<strong>सेटअप:</strong> P3 प्राधान्य, 8 कामकाजी तासांचे निराकरण लक्ष्य, UK दिनदर्शिका, "Awaiting Vendor" ही स्थिती <em>SLA थांबवा</em> म्हणून चिन्हांकित.',
            'ex3_scenario' => '<strong>परिस्थिती:</strong> तिकीट सोमवारी UK 09:00 ला नोंदवले. विश्लेषक सोमवारी UK 11:00 ला ते Microsoft कडे पाठवतो आणि तिकीट "Awaiting Vendor" स्थितीत हलवतो. Microsoft बुधवारी UK 14:00 ला उत्तर देते. विश्लेषक दुरुस्ती लागू करतो आणि गुरुवारी UK 10:00 ला तिकीट बंद करतो.',
            'ex3_timeline' => 'सोम 09:00 &mdash; तिकीट तयार झाले, निराकरणाचे घड्याळ चालू.
सोम 11:00 &mdash; "Awaiting Vendor" मध्ये हलवले, <strong>घड्याळ थांबले</strong> (2 तास वापरले).
बुध 14:00 &mdash; पुन्हा "In Progress" मध्ये हलवले, <strong>घड्याळ पुन्हा सुरू</strong>.
बुध 17:00 &mdash; कार्यालय बंद होते (एकूण 5 तास वापरले).
गुरु 09:00 &mdash; कार्यालय उघडते.
गुरु 10:00 &mdash; तिकीट बंद केले (एकूण 6 तास वापरले). 8 तासांच्या लक्ष्याविरुद्ध <strong>SLA पूर्ण झाला</strong>.',
            'ex3_outro' => 'प्रत्यक्ष घड्याळी वेळ: सुमारे 3 दिवस. SLA वेळ: 6 कामकाजी तास. थांबवण्याची स्थिती चिन्हांकित नसती, तर SLA ने विक्रेत्याच्या प्रतीक्षेचे सर्व 2 दिवस आणि कामकाजी तास मोजले असते, म्हणजे एकूण सुमारे 18 कामकाजी तास &mdash; भंग होण्याच्या कितीतरी पुढे.',
        ],
