            'r1_c' => '<code>Enforce SLAs from</code> रिकामे आहे, प्राधान्यासाठी लक्ष्ये सेट केलेली नाहीत, किंवा तिकीट कटऑफच्या आधीचे आहे.',
            'r2_s' => 'SLA भंग झाल्याचे दिसते पण विश्लेषकाने लक्ष्याच्या आत उत्तर दिले',
            'r2_c' => 'प्राधान्य बदल इतिहास तपासा &mdash; प्राधान्य मध्येच वाढवले असेल आणि वर्तन "Forward" (डीफॉल्ट) वर सेट असेल, तर जमा झालेला वेळ पुढे नेला जातो.',
            'r3_s' => 'भंगाच्या सूचना पाठवल्या जात नाहीत',
            'r3_c' => '(1) कोणतेही नियम कॉन्फिगर केलेले नाहीत. (2) Cron जॉब शेड्यूल केलेला नाही. (3) नियम कॉन्फिगर केलेले आहेत पण प्राप्तकर्ते ओळखता येत नाहीत (नेमणूक केलेला कोणी नाही, विभागाच्या संघांमध्ये ईमेल असलेले सदस्य नाहीत). प्रत्येक रनच्या सारांशासाठी Cron Activity पॅनेल तपासा.',
