            'r4_c' => 'किमान एक Default-scope नियम जोडा, म्हणजे प्रत्येक विभाग समाविष्ट होईल.',
            'r5_s' => 'Watchtower "N tickets paused over 24h" दाखवते',
            'r5_c' => 'तिकिटे SLA थांबवणाऱ्या स्थितीत पडून आहेत. एकतर कोणीतरी ती जाणीवपूर्वक ठेवली आणि विसरले, किंवा कोणीतरी On Hold चा वापर SLA मधून सुटण्याचा मार्ग म्हणून करत आहे. प्रत्येकात जा आणि एकतर प्रगती करा किंवा थांबवण्याची स्थिती काढून टाका.',
