            'tip' => 'Linux उदाहरणे आणि रिमोट-शेड्यूलर एकत्रीकरणासह cron सेटअपच्या सविस्तर तांत्रिक मार्गदर्शनासाठी, FreeITSM इन्स्टॉल डिरेक्टरीतील <code>docs/sla-cron-setup.md</code> पहा.',
